-- ==========================================================================
-- Exercise catalog, part 4 of 4: 268 exercises from the Gym visual
-- exercises dataset (media © Gym visual — https://gymvisual.com/), each with
-- its own demo GIF in the exercise-media bucket, a Spanish name checked
-- against the GIF, body part and step-by-step instructions (es/en).
-- Body parts in this part: upper legs, waist.
--
-- Additive and re-runnable: a name that already exists is skipped (and
-- listed in a notice), never overwritten. Aborts without changing anything
-- if a GIF is missing from the bucket or a GIF would end up shared.
-- Apply parts 1..4 in order in the Supabase SQL editor.
-- ==========================================================================
begin;

create temp table _new (name text, file text, body_part text, en text, es text) on commit drop;

-- 0) Every GIF and body part must exist.
do $$
declare missing text;
begin
  select string_agg(n.file, ' | ') into missing from _new n
   where not exists (select 1 from storage.objects o where o.bucket_id = 'exercise-media' and o.name = n.file);
  if missing is not null then
    raise exception 'Upload these GIFs to the exercise-media bucket first: %', missing;
  end if;
  select string_agg(distinct n.body_part, ' | ') into missing from _new n
   where not exists (select 1 from public.bodyparts b where b.name = n.body_part);
  if missing is not null then
    raise exception 'Unknown body parts: %', missing;
  end if;
end $$;

-- 1) Names that already exist are left alone.
do $$
declare taken text;
begin
  select string_agg(n.name, ' | ') into taken from _new n
   where exists (select 1 from public.exercises e where lower(e.name) = lower(n.name));
  if taken is not null then
    raise notice 'Already in the catalog, skipped: %', taken;
  end if;
end $$;

select n.name, 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || n.file, b.id, n.en::jsonb, n.es::jsonb
  from _new n
  join public.bodyparts b on b.name = n.body_part
 where not exists (select 1 from public.exercises e where lower(e.name) = lower(n.name))
   and not exists (select 1 from public.exercises e where e.video_url = 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || n.file);

-- 2) Existing exercises that had no exact GIF get theirs (only if still empty).
update public.exercises e set
  video_url = 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || v.file,
  instructions_en = v.en::jsonb, instructions_es = v.es::jsonb, updated_at = now()
from (values
  ('press de banca unilateral', 'dumbbell-lying-one-arm-press.gif', '["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.", "Hold the dumbbell at shoulder level with your palm facing forward.", "Press the dumbbell upward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Túmbate boca arriba en un banco con una mancuerna en una mano y los pies apoyados en el suelo.", "Sostén la mancuerna a la altura del hombro con la palma hacia adelante.", "Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('zancada cruzada (curtsy lunge)', 'curtsey-squat.gif', '["Stand with your feet shoulder-width apart.", "Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.", "Bend both knees as if you were curtsying, lowering your body towards the ground.", "Keep your torso upright and your weight on your front foot.", "Push through your front foot to return to the starting position.", "Repeat on the other side, stepping diagonally behind and across your body with your left foot."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.", "Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.", "Mantén el torso erguido y el peso sobre el pie delantero.", "Empuja con el pie delantero para regresar a la posición inicial.", "Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo."]')
) as v(name, file, en, es)
where lower(e.name) = v.name and e.video_url is null;

-- No GIF may be shared.
do $$
declare dup text;
begin
  select string_agg(video_url, ' | ') into dup
    from (select video_url from public.exercises
           where video_url is not null group by video_url having count(*) > 1) d;
  if dup is not null then
    raise exception 'GIF shared by more than one exercise: %', dup;
  end if;
end $$;

commit;
