insert into _new (name, file, body_part, en, es) values
  ('Estiramiento del Corredor', 'runners-stretch.gif', 'upper legs', '["Stand with your feet hip-width apart.", "Take a step forward with your right foot, keeping your left foot planted.", "Bend your right knee and lower your body down, keeping your left leg straight.", "Place your hands on your right thigh for support.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Ponte de pie con los pies separados a la altura de la cadera.", "Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.", "Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.", "Coloca las manos sobre el muslo derecho para apoyarte.", "Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]'),
  ('Extensión de Cadera a 1 Pierna en Banco', 'bench-hip-extension.gif', 'upper legs', '["Sit on a bench with your back against the bench and your feet flat on the ground.", "Place your hands on the bench for support.", "Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo.", "Coloca las manos sobre el banco para apoyarte.", "Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Cadera Inclinado con Banda Elástica', 'band-bent-over-hip-extension.gif', 'upper legs', '["Attach the band to a sturdy anchor point at ankle height.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Step back to create tension in the band, keeping your knees slightly bent.", "Hinge at the hips and lean forward, maintaining a neutral spine.", "Extend your right leg straight back, squeezing your glutes at the top.", "Lower your right leg back down and repeat with the left leg.", "Continue alternating legs for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje resistente a la altura del tobillo.", "Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.", "Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.", "Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral.", "Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior.", "Baja la pierna derecha de vuelta y repite con la pierna izquierda.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Flexión Araña', 'spider-crawl-push-up.gif', 'upper legs', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Bring your right knee towards your right elbow, keeping it off the ground.", "As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.", "Push back up to the starting position and repeat with your left knee towards your left elbow.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo.", "Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos.", "Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión con Patada Interna', 'push-up-inside-leg-kick.gif', 'upper legs', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.", "As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.", "Lower your leg back down and repeat the push-up, then switch to the other leg.", "Continue alternating leg kicks with each push-up repetition."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.", "Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta.", "Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna.", "Continúa alternando las patadas de pierna en cada repetición de la flexión."]'),
  ('Flexión con Patada Lateral', 'outside-leg-kick-push-up.gif', 'upper legs', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.", "As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.", "Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.", "Continue alternating leg kicks and push-ups for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado.", "Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos.", "Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición.", "Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado."]'),
  ('Flexión de Pica a Cobra', 'pike-to-cobra-push-up.gif', 'upper legs', '["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.", "Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.", "Lower your upper body towards the ground by bending your elbows, keeping them close to your body.", "As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.", "Reverse the movement by bending your elbows and lowering your chest back down towards the ground.", "Push through your hands to return to the inverted V position.", "Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos.", "Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo.", "Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.", "Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho.", "Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo.", "Empuja con las manos para volver a la posición de V invertida.", "Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión.", "Repite el número de repeticiones deseado."]'),
  ('Giro de Piernas Tumbado con Rodillas Flexionadas', 'bent-knee-lying-twist-male.gif', 'upper legs', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms out to the sides, perpendicular to your body.", "Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.", "Pause for a moment, then engage your core and slowly lift your knees back to the starting position.", "Repeat the movement to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Extiende los brazos hacia los lados, perpendiculares al cuerpo.", "Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.", "Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.", "Repite el movimiento hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Good Morning con Barra y Piernas Rígidas', 'barbell-stiff-leg-good-morning.gif', 'upper legs', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the barbell across your upper back, resting it on your traps.", "Keeping your back straight, hinge forward at the hips, pushing your glutes back.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Engage your glutes and hamstrings to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios.", "Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás.", "Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.", "Activa los glúteos y los isquiotibiales para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Good Morning con Rodillas Flexionadas en Máquina Smith', 'smith-bent-knee-good-morning.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart, toes pointing forward.", "Place the barbell across your upper back, resting it on your traps.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Engage your glutes and hamstrings to raise your torso back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante.", "Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.", "Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Good Morning Sentado con Barra', 'barbell-seated-good-morning.gif', 'upper legs', '["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.", "Keep your back straight and your chest up.", "Slowly hinge forward at the hips, lowering your torso towards the ground.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.", "Mantén la espalda recta y el pecho elevado.", "Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Good Morning Sentado en Máquina', 'lever-seated-good-morning.gif', 'upper legs', '["Adjust the seat height so that your hips are slightly higher than your knees.", "Sit on the machine with your back against the pad and your feet flat on the footrests.", "Grasp the handles or the sides of the seat for stability.", "Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.", "Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de modo que tus caderas queden un poco más altas que tus rodillas.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre los apoyapiés.", "Sujeta las asas o los lados del asiento para mayor estabilidad.", "Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas hasta que la parte superior de tu cuerpo quede paralela al suelo.", "Haz una pausa por un momento y luego vuelve lentamente a la posición inicial empujando con los glúteos y los isquiotibiales.", "Repite el número de repeticiones deseado."]'),
  ('Hiperextensión Inversa en Banco Plano', 'reverse-hyper-on-flat-bench.gif', 'upper legs', '["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.", "Hold onto the bench for stability.", "Keeping your legs straight, raise them up towards the ceiling as high as you can.", "Squeeze your glutes at the top of the movement.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco.", "Sujétate del banco para mantener la estabilidad.", "Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas.", "Aprieta los glúteos en la parte alta del movimiento.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Hiperextensión Inversa en Máquina', 'lever-reverse-hyperextension.gif', 'upper legs', '["Adjust the leverage machine to fit your body and secure your feet in the foot pads.", "Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.", "Cross your arms over your chest or place them behind your head.", "Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de palanca a tu cuerpo y asegura los pies en las almohadillas para los pies.", "Túmbate boca abajo en la máquina con la parte superior del cuerpo colgando fuera del borde y las caderas apoyadas en la almohadilla.", "Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.", "Activa los glúteos y los isquiotibiales para levantar las piernas hacia arriba hasta que queden paralelas al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Hiperextensión Inversa sobre Fitball', 'reverse-hyper-extension-on-stability-ball.gif', 'upper legs', '["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.", "Place your hands on the ground in front of you for stability.", "Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.", "Coloca las manos en el suelo frente a ti para mayor estabilidad.", "Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Inclinación Pélvica a Puente', 'pelvic-tilt-into-bridge.gif', 'upper legs', '["Lie on your back with your knees bent and feet flat on the ground.", "Place your arms by your sides with your palms facing down.", "Engage your glutes and core muscles.", "Tilt your pelvis upward, lifting your hips off the ground.", "Hold the bridge position for a few seconds.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.", "Activa los glúteos y los músculos del core.", "Inclina la pelvis hacia arriba, levantando las caderas del suelo.", "Mantén la posición de puente durante unos segundos.", "Baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Levantamiento Turco con Kettlebell (Estilo Sentadilla)', 'kettlebell-turkish-get-up-squat-style.gif', 'upper legs', '["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.", "Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.", "Pressing through your right foot, lift your hips off the ground, coming into a bridge position.", "Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.", "Rotate your torso to the left, bringing your left hand to the ground for support.", "Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.", "From the kneeling position, stand up, keeping the kettlebell extended overhead.", "Reverse the movement to return to the starting position.", "Repeat the exercise on the other side, starting with the kettlebell in your left hand."]', '["Comienza tumbado boca arriba con las piernas extendidas y la pesa rusa sostenida en la mano derecha, con el brazo completamente extendido por encima del hombro.", "Flexiona la rodilla derecha y coloca el pie derecho plano en el suelo, manteniendo la pierna izquierda extendida.", "Presionando con el pie derecho, levanta las caderas del suelo, llegando a una posición de puente.", "Desliza la pierna izquierda por debajo del cuerpo, flexionando la rodilla izquierda y colocando el pie izquierdo plano en el suelo.", "Rota el torso hacia la izquierda, llevando la mano izquierda al suelo como apoyo.", "Presionando con el pie derecho y la mano izquierda, levanta el torso del suelo, llegando a una posición de rodillas.", "Desde la posición de rodillas, ponte de pie, manteniendo la pesa rusa extendida por encima de la cabeza.", "Invierte el movimiento para volver a la posición inicial.", "Repite el ejercicio en el otro lado, comenzando con la pesa rusa en la mano izquierda."]'),
  ('Paso Lateral con Banda (Monster Walk)', 'monster-walk.gif', 'upper legs', '["Place a resistance band around your ankles.", "Stand with your feet shoulder-width apart and slightly bend your knees.", "Take a step to the side with your right foot, maintaining tension on the resistance band.", "Follow with your left foot, stepping to the side to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Coloca una banda elástica alrededor de los tobillos.", "Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.", "Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica.", "Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Patadas de Nadador Boca Abajo', 'swimmer-kicks-v-2-male.gif', 'upper legs', '["Lie face down on a mat with your arms extended overhead.", "Engage your core and lift your chest and legs off the ground simultaneously.", "Kick your legs up and down in a fluttering motion, as if you were swimming.", "Continue kicking for the desired number of repetitions.", "Lower your chest and legs back down to the starting position."]', '["Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza.", "Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo.", "Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando.", "Continúa el movimiento de patada el número de repeticiones deseado.", "Baja el pecho y las piernas de nuevo a la posición inicial."]'),
  ('Patadas de Tijera (Flutter Kicks)', 'flutter-kicks.gif', 'upper legs', '["Lie flat on your back with your legs extended and your hands by your sides.", "Engage your core and lift your legs off the ground about 6 inches.", "Keeping your legs straight, alternate lifting one leg slightly higher than the other.", "Continue this fluttering motion for the desired number of repetitions."]', '["Túmbate boca arriba con las piernas extendidas y las manos a los costados.", "Activa el core y levanta las piernas del suelo unos 15 centímetros.", "Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.", "Continúa este movimiento de aleteo durante el número de repeticiones deseado."]'),
  ('Peso Muerto a 1 Pierna con Mancuernas', 'dumbbell-single-leg-deadlift.gif', 'upper legs', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.", "Shift your weight onto your left leg and lift your right foot slightly off the ground.", "Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.", "At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.", "Lower the dumbbell until your torso and right leg are parallel to the ground.", "Pause for a moment, then engage your glutes and hamstrings to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.", "Traslada tu peso a la pierna izquierda y levanta el pie derecho ligeramente del suelo.", "Manteniendo la espalda recta, inclínate hacia adelante desde las caderas y baja la mancuerna hacia el suelo.", "Al mismo tiempo, extiende la pierna derecha recta hacia atrás, manteniendo una ligera flexión en la rodilla izquierda.", "Baja la mancuerna hasta que tu torso y tu pierna derecha queden paralelos al suelo.", "Haz una pausa por un momento, luego activa los glúteos y los isquiotibiales para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Peso Muerto a 1 Pierna con Mancuernas y Apoyo en Step', 'dumbbell-single-leg-deadlift-with-stepbox-support.gif', 'upper legs', '["Stand with your feet hip-width apart, holding a dumbbell in your right hand.", "Place your left foot on a stepbox or elevated surface behind you.", "Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.", "As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.", "Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de las caderas, sujetando una mancuerna con la mano derecha.", "Coloca el pie izquierdo sobre un cajón de step o una superficie elevada detrás de ti.", "Manteniendo la espalda recta y el core activado, inclínate hacia adelante desde las caderas, bajando la mancuerna hacia el suelo.", "Mientras bajas la mancuerna, levanta al mismo tiempo la pierna izquierda detrás de ti, manteniendo una línea recta desde la cabeza hasta el talón.", "Baja la mancuerna hasta sentir un estiramiento en el isquiotibial derecho, luego vuelve a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Peso Muerto con Piernas Rectas con Mancuernas', 'dumbbell-straight-leg-deadlift.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.", "Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.", "Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que el torso se incline hacia adelante.", "Continúa bajando las mancuernas hasta sentir un estiramiento en los isquiotibiales, manteniendo las rodillas ligeramente flexionadas.", "Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Peso Muerto con Piernas Rígidas con Mancuernas', 'dumbbell-stiff-leg-deadlift.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.", "Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo una ligera flexión en las rodillas.", "Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego aprieta los glúteos y empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Peso Muerto en Máquina', 'lever-deadlift.gif', 'upper legs', '["Adjust the seat height and foot platform to your desired position.", "Sit on the machine with your back against the pad and your feet flat on the foot platform.", "Grasp the handles or the sides of the seat for stability.", "Engage your glutes and hamstrings, and push through your heels to lift the weight up.", "Keep your back straight and avoid rounding your shoulders.", "Extend your hips fully at the top of the movement, squeezing your glutes.", "Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.", "Siéntate en la máquina con la espalda apoyada en la almohadilla y los pies planos sobre la plataforma para los pies.", "Sujeta las asas o los lados del asiento para mayor estabilidad.", "Activa los glúteos y los isquiotibiales, y empuja con los talones para levantar el peso.", "Mantén la espalda recta y evita redondear los hombros.", "Extiende por completo las caderas en la parte alta del movimiento, apretando los glúteos.", "Baja el peso de manera controlada, manteniendo la tensión en los glúteos y los isquiotibiales.", "Repite el número de repeticiones deseado."]'),
  ('Peso Muerto en Máquina Smith', 'smith-deadlift.gif', 'upper legs', '["Set up the smith machine with the bar at hip height.", "Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.", "Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.", "Stand up straight, fully extending your hips and knees.", "Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de la cadera.", "Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros.", "Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo.", "Ponte de pie erguido, extendiendo por completo las caderas y las rodillas.", "Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta.", "Repite el número de repeticiones deseado."]'),
  ('Peso Muerto en Polea', 'cable-deadlift.gif', 'upper legs', '["Stand facing the cable machine with your feet shoulder-width apart.", "Bend at the hips and knees, lowering your torso until your back is parallel to the ground.", "Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.", "Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.", "Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.", "Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.", "Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie.", "Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Peso Muerto Lateral a 1 Brazo con Barra', 'barbell-one-arm-side-deadlift.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.", "Keep your back straight and your core engaged.", "Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.", "Lower the barbell as far as you can while maintaining good form.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.", "Mantén la espalda recta y el core activado.", "Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.", "Baja la barra tanto como puedas manteniendo una buena forma.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Peso Muerto Rumano con Mancuernas', 'dumbbell-romanian-deadlift.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.", "Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente.", "Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pies Rápidos (Quick Feet)', 'quick-feet-v-2.gif', 'upper legs', '["Stand with your feet shoulder-width apart and your arms by your sides.", "Begin by rapidly moving your feet up and down, as if you were running in place.", "Keep your movements quick and light, focusing on staying on the balls of your feet.", "Continue for the desired duration or number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.", "Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio.", "Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies.", "Continúa durante el tiempo o el número de repeticiones deseado."]'),
  ('Postura de Mariposa (Yoga)', 'butterfly-yoga-pose.gif', 'upper legs', '["Sit on the floor with your legs extended in front of you.", "Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.", "Hold onto your ankles or feet with your hands.", "Sit up tall and lengthen your spine.", "Gently press your knees down towards the floor, feeling a stretch in your inner thighs.", "Hold this position for a few breaths.", "To release, slowly bring your knees back up and extend your legs."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.", "Sujétate los tobillos o los pies con las manos.", "Siéntate erguido y alarga la columna.", "Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.", "Mantén esta posición durante unas cuantas respiraciones.", "Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas."]'),
  ('Prensa de Piernas 45° con Pies Abiertos', 'sled-45-leg-wide-press.gif', 'upper legs', '["Adjust the sled machine to a 45-degree angle.", "Sit on the sled machine with your back against the pad and your feet on the foot platform.", "Position your feet wider than shoulder-width apart.", "Push against the foot platform to extend your legs and straighten your knees.", "Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un ángulo de 45 grados.", "Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.", "Coloca los pies más separados que el ancho de los hombros.", "Empuja contra la plataforma para extender las piernas y enderezar las rodillas.", "Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Prensa de Piernas Alterna en Máquina', 'lever-alternate-leg-press.gif', 'upper legs', '["Adjust the seat and foot platform of the leverage machine to your desired position.", "Sit on the machine with your back against the backrest and your feet on the foot platform.", "Place your hands on the handles or sides of the machine for stability.", "Push one foot against the foot platform, extending your leg until it is almost fully straight.", "Pause for a moment, then slowly bend your leg and return to the starting position.", "Repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."]', '["Ajusta el asiento y la plataforma para los pies de la máquina de palanca a la posición deseada.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma para los pies.", "Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.", "Empuja un pie contra la plataforma para los pies, extendiendo la pierna hasta que esté casi completamente recta.", "Haz una pausa breve, luego flexiona lentamente la pierna y vuelve a la posición inicial.", "Repite con la otra pierna.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Prensa de Piernas en Máquina Smith', 'smith-leg-press.gif', 'upper legs', '["Adjust the seat and footplate of the smith machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Grasp the handles or sides of the machine for stability.", "Push the footplate away from you by extending your legs, keeping your back against the backrest.", "Pause for a moment at the fully extended position.", "Slowly bend your knees and lower the footplate back towards you, returning to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.", "Sujeta las asas o los lados de la máquina para mayor estabilidad.", "Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo.", "Haz una pausa por un momento en la posición completamente extendida.", "Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Prensa Horizontal a 1 Pierna en Máquina', 'lever-horizontal-one-leg-press.gif', 'upper legs', '["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.", "Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.", "Place your hands on the handles or sides of the machine for stability.", "Push the footplate away from your body by extending your leg, keeping your back against the backrest.", "Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ajusta el asiento de la máquina de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa para los pies.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies.", "Coloca las manos en las asas o en los lados de la máquina para mayor estabilidad.", "Empuja la placa para los pies alejándola del cuerpo extendiendo la pierna, manteniendo la espalda apoyada en el respaldo.", "Haz una pausa breve en la posición completamente extendida, luego flexiona lentamente la pierna para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Puente de Glúteo con Barra', 'barbell-glute-bridge-1409.gif', 'upper legs', '["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.", "Place a barbell across your hips, holding it securely with both hands.", "Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.", "Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.", "Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Haz una pausa breve en la parte alta, apretando los glúteos.", "Baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Puente de Glúteo con Barra y Pies en Banco', 'barbell-glute-bridge-two-legs-on-bench-male.gif', 'upper legs', '["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.", "Place a barbell across your hips, holding it securely with both hands.", "Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.", "Pause for a moment at the top, squeezing your glutes.", "Slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.", "Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.", "Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.", "Haz una pausa breve en la parte alta, apretando los glúteos.", "Baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Puente de Glúteo con Marcha', 'glute-bridge-march.gif', 'upper legs', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.", "Lower your foot back to the ground and repeat the movement with the other leg.", "Continue alternating legs in a marching motion while maintaining the bridge position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.", "Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho.", "Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna.", "Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente.", "Repite el número de repeticiones deseado."]'),
  ('Puente de Glúteo con Pies en Banco', 'glute-bridge-two-legs-on-bench-male.gif', 'upper legs', '["Sit on the edge of a bench with your back against it and your feet flat on the ground.", "Place your hands on the bench beside your hips for support.", "Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco con la espalda apoyada en él y los pies planos sobre el suelo.", "Coloca las manos en el banco junto a las caderas para mayor apoyo.", "Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Puente Declinado Inverso', 'rear-decline-bridge.gif', 'upper legs', '["Lie on your back with your feet flat on the ground and your knees bent.", "Place your arms by your sides with your palms facing down.", "Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Hold this position for a few seconds, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas.", "Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.", "Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pull Through con Banda Elástica', 'band-pull-through.gif', 'upper legs', '["Attach a resistance band to a sturdy anchor point at ground level.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Step forward to create tension in the band, keeping your knees slightly bent.", "Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.", "Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.", "Drive your hips forward and squeeze your glutes to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.", "Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.", "Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.", "Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.", "Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.", "Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pull Through en Polea con Cuerda', 'cable-pull-through-with-rope.gif', 'upper legs', '["Stand facing away from the cable machine with your feet shoulder-width apart.", "Grab the rope attachment with both hands and step forward, creating tension in the cable.", "Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.", "Engage your glutes and hamstrings to pull your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.", "Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable.", "Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta.", "Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pull Through Sumo con Mancuerna', 'dumbbell-sumo-pull-through.gif', 'upper legs', '["Stand with your feet wider than shoulder-width apart, toes pointed outwards.", "Hold a dumbbell with both hands in front of your body, arms extended.", "Bend your knees and lower your hips down into a squat position, keeping your back straight.", "Lower the dumbbell down between your legs, keeping your arms straight.", "Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.", "Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies más separados que la altura de los hombros, con las puntas de los pies hacia afuera.", "Sujeta una mancuerna con ambas manos frente a tu cuerpo, con los brazos extendidos.", "Flexiona las rodillas y baja las caderas hasta una posición de sentadilla, manteniendo la espalda recta.", "Baja la mancuerna entre las piernas, manteniendo los brazos rectos.", "Empuja con los talones y extiende las caderas hacia adelante, llevando la mancuerna hacia arriba y frente a tu cuerpo.", "Aprieta los glúteos en la parte superior del movimiento, luego baja la mancuerna de vuelta entre las piernas.", "Repite el número de repeticiones deseado."]'),
  ('Rack Pull con Barra', 'barbell-rack-pull.gif', 'upper legs', '["Set up a barbell on a rack at knee height.", "Stand with your feet shoulder-width apart, toes pointing slightly outwards.", "Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.", "Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.", "Lower the barbell back down to the starting position by bending at the hips and knees.", "Repeat for the desired number of repetitions."]', '["Coloca una barra en un soporte a la altura de la rodilla.", "Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.", "Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.", "Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.", "Repite el número de repeticiones deseado."]'),
  ('Rotación de Cadera a 1 Pierna Boca Abajo sobre Fitball', 'exercise-ball-one-leg-prone-lower-body-rotation.gif', 'upper legs', '["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.", "Place your hands on the ground in front of you for support.", "Engage your glutes and core muscles to stabilize your body.", "Slowly lift one leg off the ground, keeping it straight and parallel to the floor.", "Rotate your leg outward, away from your body, while keeping your hips and upper body stable.", "Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.", "Repeat the rotation with the other leg.", "Continue alternating legs for the desired number of repetitions."]', '["Túmbate boca abajo sobre el balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti.", "Coloca las manos en el suelo frente a ti para mayor apoyo.", "Activa los glúteos y el abdomen para estabilizar el cuerpo.", "Levanta lentamente una pierna del suelo, manteniéndola recta y paralela al piso.", "Gira la pierna hacia afuera, alejándola del cuerpo, mientras mantienes las caderas y la parte superior del cuerpo estables.", "Haz una pausa al final de la rotación, luego regresa lentamente la pierna a la posición inicial.", "Repite la rotación con la otra pierna.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Rotación Interna de Cadera Sentado con Banda Elástica', 'band-seated-hip-internal-rotation.gif', 'upper legs', '["Sit on a chair or bench with your back straight and feet flat on the ground.", "Place a resistance band around your thighs, just above your knees.", "Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.", "Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.", "Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.", "Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.", "Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.", "Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rotación Interna de Cadera Tumbado con Banda Elástica', 'band-lying-hip-internal-rotation.gif', 'upper legs', '["Lie on your back with your legs straight and a resistance band looped around your feet.", "Bend your knees and bring them towards your chest, keeping your feet together.", "Slowly rotate your knees outwards, away from each other, while keeping your feet together.", "Pause for a moment at the end of the rotation, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.", "Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.", "Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.", "Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Salto desde Rodillas a Sentadilla con Barra', 'kneeling-jump-squat.gif', 'upper legs', '["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.", "Hold a barbell across your upper back, resting it on your shoulders.", "Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.", "As you jump, push through your toes and fully extend your ankles, knees, and hips.", "Land softly back on the ground, bending your knees to absorb the impact.", "Immediately go into the next repetition, repeating the jump squat motion."]', '["Comienza arrodillado en el suelo con los pies separados a la altura de las caderas y los dedos de los pies apuntando hacia adelante.", "Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.", "Activa el core y los glúteos, luego salta explosivamente hacia arriba, extendiendo las caderas y las rodillas.", "Mientras saltas, empuja con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas.", "Aterriza suavemente de vuelta en el suelo, flexionando las rodillas para absorber el impacto.", "Pasa de inmediato a la siguiente repetición, repitiendo el movimiento de sentadilla con salto."]'),
  ('Salto hacia Adelante', 'forward-jump.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Bend your knees and lower your body into a squat position.", "Swing your arms back for momentum.", "Jump forward explosively, extending your hips, knees, and ankles.", "Land softly on the balls of your feet and immediately go into the next jump.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.", "Balancea los brazos hacia atrás para generar impulso.", "Salta hacia adelante de forma explosiva, extendiendo las caderas, las rodillas y los tobillos.", "Aterriza suavemente sobre la punta de los pies y pasa de inmediato al siguiente salto.", "Repite el número de repeticiones deseado."]'),
  ('Salto hacia Atrás', 'backward-jump.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Bend your knees slightly and jump backwards, pushing off with both feet.", "Land softly on the balls of your feet, bending your knees to absorb the impact.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.", "Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.", "Repite el número de repeticiones deseado."]'),
  ('Secuencia de Piernas Abiertas Sentado (Yoga)', 'seated-wide-angle-pose-sequence.gif', 'upper legs', '["Sit on the ground with your legs extended in a wide angle.", "Flex your feet and engage your quadriceps.", "Place your hands on the ground behind you for support.", "Keeping your back straight, lean forward from your hips.", "Continue leaning forward until you feel a stretch in your hamstrings.", "Hold this position for a few breaths.", "Slowly release the stretch and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas formando un ángulo amplio.", "Flexiona los pies y contrae los cuádriceps.", "Coloca las manos en el suelo detrás de ti para apoyarte.", "Manteniendo la espalda recta, inclínate hacia delante desde la cadera.", "Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales.", "Mantén esta posición durante unas cuantas respiraciones.", "Libera lentamente el estiramiento y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla a 1 Pierna con Barra y Pie Trasero Elevado', 'barbell-one-leg-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.", "Lift one foot off the ground and extend it forward, keeping it parallel to the ground.", "Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.", "Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.", "Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.", "Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.", "Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Sentadilla a 1 Pierna con Mancuernas', 'dumbbell-single-leg-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Extend one leg forward and keep it off the ground throughout the exercise.", "Bend your standing leg and lower your body down as if sitting back into a chair.", "Keep your chest up and your back straight.", "Pause for a moment at the bottom, then push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Extiende una pierna hacia adelante y mantenla levantada del suelo durante todo el ejercicio.", "Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.", "Mantén el pecho arriba y la espalda recta.", "Haz una pausa por un momento en la posición más baja, luego empuja con el talón para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla a 1 Pierna con Pie en Cajón', 'one-leg-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Extend one leg forward, keeping it off the ground.", "Bend your standing leg and lower your body down as if sitting back into a chair.", "Keep your chest up and your back straight.", "Push through your heel to return to the starting position.", "Repeat with the other leg."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Extiende una pierna hacia adelante, manteniéndola elevada del suelo.", "Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla.", "Mantén el pecho arriba y la espalda recta.", "Empuja con el talón para regresar a la posición inicial.", "Repite con la otra pierna."]'),
  ('Sentadilla a Banco con Barra', 'barbell-bench-squat-0026.gif', 'upper legs', '["Set up a barbell on a squat rack at chest height.", "Stand facing away from the rack, with your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.", "Lower your body down into a squat, keeping your knees in line with your toes.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra en un soporte de sentadillas a la altura del pecho.", "Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.", "Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla a Banco con Mancuernas', 'dumbbell-bench-squat.gif', 'upper legs', '["Place a dumbbell on the ground in front of a bench.", "Stand facing away from the bench with your feet shoulder-width apart.", "Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.", "Once your glutes touch the bench, push through your heels to stand back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una mancuerna en el suelo frente a un banco.", "Ponte de pie de espaldas al banco con los pies separados a la altura de los hombros.", "Flexiona las rodillas y las caderas para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta.", "Una vez que los glúteos toquen el banco, empuja con los talones para volver a ponerte de pie en la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla a Silla en Máquina Smith', 'smith-chair-squat.gif', 'upper legs', '["Adjust the height of the smith machine bar to a comfortable position.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Place the barbell across your upper back, resting it on your traps.", "Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura de la barra de la máquina Smith a una posición cómoda.", "Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.", "Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Abierta con Barra', 'barbell-wide-squat.gif', 'upper legs', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.", "Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.", "Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Búlgara a 1 Brazo con Banda Elástica', 'band-one-arm-single-leg-split-squat.gif', 'upper legs', '["Stand with your feet hip-width apart and place a resistance band around your ankles.", "Extend one leg forward and rest the top of your foot on a bench or step behind you.", "Hold onto a support with one hand for balance.", "Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.", "Push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.", "Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.", "Sujétate de un apoyo con una mano para mantener el equilibrio.", "Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.", "Empuja con el talón para regresar a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla Búlgara con Banda Elástica', 'band-single-leg-split-squat.gif', 'upper legs', '["Stand with your feet hip-width apart and place a resistance band around your ankles.", "Take a big step forward with your right foot and a smaller step back with your left foot.", "Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.", "Push through your right heel to return to the starting position.", "Repeat on the other side."]', '["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.", "Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.", "Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.", "Empuja con el talón derecho para regresar a la posición inicial.", "Repite del otro lado."]'),
  ('Sentadilla Búlgara con Barra', 'barbell-single-leg-split-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a large step forward with one leg, keeping your torso upright.", "Lower your body by bending your front knee and hip, while keeping your back leg straight.", "Continue lowering until your front thigh is parallel to the ground.", "Pause for a moment, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.", "Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.", "Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.", "Continúa bajando hasta que el muslo delantero quede paralelo al suelo.", "Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla Búlgara en Máquina Smith', 'smith-single-leg-split-squat.gif', 'upper legs', '["Stand in front of the smith machine with your feet shoulder-width apart.", "Place one foot behind you on a bench or step, with your toes pointing forward.", "Hold onto the smith machine bar for stability.", "Bend your front knee and lower your body down into a lunge position, keeping your back straight.", "Pause for a moment at the bottom, then push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.", "Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante.", "Sujétate de la barra de la máquina Smith para mayor estabilidad.", "Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.", "Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla Búlgara sin Peso', 'quads.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Lower your body by bending your knees and pushing your hips back as if sitting on a chair.", "Keep your chest up and your back straight.", "Lower yourself until your thighs are parallel to the ground.", "Push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.", "Mantén el pecho arriba y la espalda recta.", "Baja hasta que los muslos queden paralelos al suelo.", "Empuja con los talones para volver a ponerte de pie en la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Alcance por Encima de la Cabeza', 'squat-to-overhead-reach.gif', 'upper legs', '["Stand with your feet shoulder-width apart and toes slightly turned out.", "Lower your body down into a squat position by bending your knees and pushing your hips back.", "As you come up from the squat, extend your arms overhead, reaching towards the ceiling.", "Return to the starting position by lowering your arms and bending your knees to squat down again.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo.", "Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Alcance y Giro', 'squat-to-overhead-reach-with-twist.gif', 'upper legs', '["Stand with your feet shoulder-width apart and toes slightly turned out.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "As you come up from the squat, raise your arms overhead and twist your torso to one side.", "Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.", "Continue alternating sides with each squat repetition."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado.", "Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto.", "Continúa alternando los lados en cada repetición de la sentadilla."]'),
  ('Sentadilla con Barra Baja en Máquina Smith', 'smith-low-bar-squat.gif', 'upper legs', '["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.", "Stand with your feet shoulder-width apart, toes slightly turned outwards.", "Step under the bar and position it across your upper back, resting it on your traps.", "Grip the bar with your hands slightly wider than shoulder-width apart.", "Unrack the bar by straightening your legs and stepping back from the rack.", "Take a deep breath and brace your core.", "Initiate the squat by pushing your hips back and bending your knees.", "Lower your body until your thighs are parallel to the ground or slightly below.", "Keep your chest up and your back straight throughout the movement.", "Drive through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda.", "Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.", "Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.", "Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte.", "Respira profundamente y tensa el core.", "Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.", "Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.", "Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.", "Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Barra y Pies Juntos', 'barbell-narrow-stance-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and toes pointing slightly outward.", "Hold the barbell across your upper back, resting it on your traps or rear delts.", "Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.", "Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.", "Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Cinturón de Lastre', 'weighted-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Hold a weight in front of your chest or on your shoulders.", "Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Push through your heels to stand back up, squeezing your glutes at the top.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Sostén un peso frente al pecho o sobre los hombros.", "Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.", "Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Jerk', 'squat-jerk.gif', 'upper legs', '["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.", "Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.", "As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.", "As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.", "Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.", "Stand up from the split position, bringing your feet back together.", "Lower the barbell back to your shoulders and repeat for the desired number of repetitions."]', '["Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros.", "Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies.", "Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza.", "Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás.", "Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo.", "Ponte de pie desde la posición dividida, juntando de nuevo los pies.", "Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado."]'),
  ('Sentadilla con Mancuerna y Apoyo', 'dumbbell-supported-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.", "Manteniendo el pecho arriba y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Remo con Banda Elástica', 'band-squat-row.gif', 'upper legs', '["Attach the band to a sturdy anchor point at waist height.", "Stand facing the anchor point with your feet shoulder-width apart.", "Hold the band handles with your palms facing each other and your arms extended in front of you.", "Bend your knees and lower into a squat position, keeping your back straight and chest lifted.", "From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.", "Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.", "Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.", "Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Salto con Barra', 'barbell-jump-squat.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Once you reach the bottom of the squat, explode upwards by jumping off the ground.", "As you jump, extend your hips, knees, and ankles, pushing through your toes.", "Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.", "Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.", "Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado."]'),
  ('Sentadilla con Salto desde Caída', 'bodyweight-drop-jump-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Jump up explosively, extending your hips, knees, and ankles.", "While in mid-air, quickly bring your feet together.", "Land softly on the balls of your feet and immediately drop back into a squat position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos.", "Mientras estás en el aire, junta rápidamente los pies.", "Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Salto y Zancada Atrás con Barra', 'barbell-squat-jump-step-rear-lunge.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "Explode upwards, jumping off the ground as high as you can.", "Land softly on your feet and immediately step back with one leg into a reverse lunge.", "Lower your body down until your front thigh is parallel to the ground, keeping your back straight.", "Push through your front heel to return to the starting position.", "Repeat the jump and lunge sequence on the other leg.", "Continue alternating legs for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas.", "Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa.", "Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.", "Empuja con el talón delantero para volver a la posición inicial.", "Repite la secuencia de salto y zancada con la otra pierna.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Sentadilla Cosaca con Peso', 'weighted-cossack-squats-male.gif', 'upper legs', '["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.", "Hold a weight in front of your chest with both hands.", "Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.", "Go as low as you can while maintaining balance and keeping your chest up.", "Push through the heel of the bent leg to return to the starting position.", "Repeat on the other side, alternating between legs."]', '["Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera.", "Sostén un peso frente al pecho con ambas manos.", "Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta.", "Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado.", "Empuja con el talón de la pierna flexionada para volver a la posición inicial.", "Repite con el otro lado, alternando entre las piernas."]'),
  ('Sentadilla de Rodillas con Barra', 'barbell-squat-on-knees.gif', 'upper legs', '["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.", "Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.", "Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante.", "Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Dividida con Barra en las Manos', 'barbell-split-squat-v-2.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.", "Take a large step forward with your right foot, keeping your torso upright.", "Lower your body by bending your knees and hips until your right thigh is parallel to the ground.", "Pause for a moment, then push through your right heel to return to the starting position.", "Repeat with your left leg forward for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.", "Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido.", "Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo.", "Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial.", "Repite con la pierna izquierda adelante el número de repeticiones deseado."]'),
  ('Sentadilla Dividida con Pie Delantero en Banco', 'dumbbell-step-up-split-squat.gif', 'upper legs', '["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.", "Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.", "Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.", "As you step up, simultaneously lift your left knee towards your chest.", "Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.", "Repeat the movement with your left foot on the bench or step.", "Continue alternating between your right and left foot for the desired number of repetitions."]', '["Ponte de pie frente a un banco o escalón con una mancuerna en cada mano, con las palmas hacia tu cuerpo.", "Coloca el pie derecho sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.", "Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo.", "Mientras subes, levanta al mismo tiempo la rodilla izquierda hacia el pecho.", "Haz una pausa en la parte superior del movimiento, luego baja lentamente el pie izquierdo de vuelta al suelo mientras mantienes el pie derecho sobre el banco o escalón.", "Repite el movimiento con el pie izquierdo sobre el banco o escalón.", "Continúa alternando entre el pie derecho y el izquierdo durante el número de repeticiones deseado."]'),
  ('Sentadilla Dividida en Suspensión (TRX)', 'suspended-split-squat-0809.gif', 'upper legs', '["Stand facing away from a suspension trainer with your feet shoulder-width apart.", "Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.", "Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.", "Push through your heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros.", "Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión.", "Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie.", "Empuja con el talón para regresar a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla en Pared con Patada', 'kick-out-sit.gif', 'upper legs', '["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lean back slightly and place your hands on the edge of the bench or chair for support.", "Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.", "Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco o una silla con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Inclínate ligeramente hacia atrás y coloca las manos en el borde del banco o la silla como apoyo.", "Activando los isquiotibiales, levanta los pies del suelo y extiende las piernas rectas hacia adelante.", "Haz una pausa breve en lo alto, luego flexiona lentamente las rodillas y lleva los pies de vuelta hacia el cuerpo.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frankenstein', 'frankenstein-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.", "Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra frente al cuerpo con los brazos rectos.", "Manteniendo la espalda recta, baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frontal a Banco con Barra', 'barbell-bench-front-squat.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.", "Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.", "Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.", "Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.", "Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.", "Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frontal con Agarre de Cargada', 'barbell-clean-grip-front-squat.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.", "Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.", "Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.", "Repeat for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.", "Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.", "Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frontal con Brazos Cruzados', 'barbell-front-chest-squat.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart, toes slightly turned out.", "Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.", "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.", "Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frontal con Kettlebells', 'kettlebell-front-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the kettlebell with both hands in front of your chest, close to your body.", "Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.", "Lower until your thighs are parallel to the ground, or as low as you can comfortably go.", "Drive through your heels to stand back up, squeezing your glutes at the top.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Sujeta la pesa rusa con ambas manos frente al pecho, cerca del cuerpo.", "Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla.", "Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Frontal en Máquina Smith', 'smith-front-squat-clean-grip.gif', 'upper legs', '["Set up the smith machine with the barbell at shoulder height.", "Stand facing the barbell with your feet shoulder-width apart.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.", "Keep your chest up, back straight, and core engaged.", "Lower your body by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de los hombros.", "Ponte de pie frente a la barra con los pies separados a la altura de los hombros.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides.", "Mantén el pecho elevado, la espalda recta y el core activado.", "Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla.", "Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Goblet con Kettlebell', 'kettlebell-goblet-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.", "Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa cerca del pecho con ambas manos.", "Manteniendo el pecho elevado y el core activado, baja el cuerpo a una posición de sentadilla flexionando las rodillas y las caderas.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Hack Cerrada en Máquina', 'sled-closer-hack-squat.gif', 'upper legs', '["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.", "Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.", "Grip the handles on the sides of the machine for stability.", "Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo.", "Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera.", "Sujeta las asas a los lados de la máquina para mayor estabilidad.", "Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta.", "Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.", "Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Hack con Barra (Barra por Detrás)', 'barbell-hack-squat-0046.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart and your toes slightly turned out.", "Hold the barbell behind your legs, resting it on your upper thighs.", "Lower your body by bending at the knees and hips, keeping your back straight and your chest up.", "Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.", "Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Hack en Máquina Smith', 'smith-hack-squat.gif', 'upper legs', '["Adjust the barbell on the smith machine to an appropriate height for your body.", "Stand with your feet shoulder-width apart, toes slightly pointed outwards.", "Position yourself under the barbell, resting it on your upper traps and shoulders.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and keep your chest up as you unrack the barbell.", "Take a step back and position your feet slightly wider than shoulder-width apart.", "Bend your knees and lower your body down, keeping your chest up and back straight.", "Continue descending until your thighs are parallel to the ground or slightly below.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo.", "Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte.", "Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros.", "Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta.", "Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Jefferson con Barra', 'barbell-jefferson-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.", "Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.", "Push through your heels to stand back up to the starting position.", "Repeat the movement, alternating your forward and back foot with each repetition."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.", "Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Empuja con los talones para volver a ponerte de pie en la posición inicial.", "Repite el movimiento, alternando el pie delantero y el trasero en cada repetición."]'),
  ('Sentadilla Lateral con Barra (Cossack)', 'barbell-side-split-squat.gif', 'upper legs', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold a barbell across your upper back, resting it on your traps.", "Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.", "As you lower, push your knees out to the sides and keep your weight on your heels.", "Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.", "Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.", "Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.", "Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.", "Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Pistol con Kettlebell', 'kettlebell-pistol-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.", "Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.", "Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.", "Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.", "Levanta el pie izquierdo del suelo y extiéndelo hacia adelante, manteniéndolo paralelo al suelo.", "Baja lentamente el cuerpo a una posición de sentadilla, manteniendo el pie derecho plano en el suelo y la pierna izquierda extendida.", "Haz una pausa breve en la parte baja de la sentadilla, luego empuja con el talón derecho para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Sentadilla por Encima de la Cabeza con Barra', 'barbell-overhead-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and toes slightly turned out.", "Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.", "Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.", "Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Profunda con Apoyo', 'potty-squat-with-support.gif', 'upper legs', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Hold onto a stable support, such as a chair or wall, for balance.", "Lower your body down into a squat position by bending your knees and pushing your hips back.", "Keep your chest up and your back straight throughout the movement.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Profunda en Máquina Smith', 'smith-full-squat.gif', 'upper legs', '["Set up the smith machine with the barbell at shoulder height.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Step under the bar and position it across your upper back, resting on your traps.", "Grip the bar with your hands slightly wider than shoulder-width apart.", "Unrack the bar and take a step back, maintaining a stable stance.", "Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.", "Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.", "Pause for a moment at the bottom, then drive through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de los hombros.", "Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.", "Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios.", "Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.", "Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable.", "Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas.", "Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita.", "Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Sissy con Disco', 'weighted-sissy-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart and your toes pointing slightly outward.", "Hold a weight in front of your chest with both hands, or place a barbell across your upper back.", "Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.", "Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.", "Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda.", "Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas.", "Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla sobre Bosu', 'squat-on-bosu-ball.gif', 'upper legs', '["Place the bosu ball on the ground with the flat side up.", "Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.", "Lower your body down by bending your knees and hips, as if sitting back into a chair.", "Keep your chest up and your weight on your heels.", "Lower yourself until your thighs are parallel to the ground.", "Pause for a moment, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca el bosu en el suelo con el lado plano hacia arriba.", "Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu.", "Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla.", "Mantén el pecho elevado y el peso en los talones.", "Baja hasta que los muslos queden paralelos al suelo.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Sumo en Máquina Smith', 'smith-sumo-squat.gif', 'upper legs', '["Set up the smith machine with the barbell at hip height.", "Stand with your feet wider than shoulder-width apart, toes pointing outwards.", "Position yourself under the barbell, resting it on your upper back and shoulders.", "Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.", "Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de la cadera.", "Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera.", "Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros.", "Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Sumo Pliométrica con Mancuerna', 'dumbbell-plyo-squat.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Lower your body into a squat position by bending your knees and pushing your hips back.", "As you reach the bottom of the squat, explode upward, jumping off the ground.", "While in the air, quickly switch the position of your feet, landing with your opposite foot forward.", "Immediately lower your body back into a squat position and repeat the jump, switching your feet again.", "Continue alternating the position of your feet with each jump for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.", "Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.", "Cuando llegues al punto más bajo de la sentadilla, impúlsate explosivamente hacia arriba, saltando del suelo.", "Mientras estás en el aire, cambia rápidamente la posición de los pies, aterrizando con el pie opuesto adelante.", "Baja inmediatamente el cuerpo de vuelta a la posición de sentadilla y repite el salto, cambiando de nuevo los pies.", "Continúa alternando la posición de los pies en cada salto durante el número de repeticiones deseado."]'),
  ('Sentadilla Tumbado en Máquina', 'sled-lying-squat.gif', 'upper legs', '["Adjust the sled machine to a comfortable weight.", "Lie on your back on the sled machine with your feet on the footplate.", "Position your feet shoulder-width apart and slightly angled outwards.", "Grip the handles of the sled machine for stability.", "Engage your glutes and core muscles.", "Push through your heels and extend your legs to lift the sled.", "Lower the sled back down by bending your knees and hips.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un peso adecuado.", "Túmbate boca arriba en la máquina de trineo con los pies sobre la placa.", "Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera.", "Sujeta las asas de la máquina de trineo para mayor estabilidad.", "Activa los glúteos y los músculos del core.", "Empuja con los talones y extiende las piernas para levantar el trineo.", "Baja el trineo de nuevo doblando las rodillas y las caderas.", "Repite el número de repeticiones deseado."]'),
  ('Step-Up con Banda Elástica', 'band-step-up.gif', 'upper legs', '["Place a band around your thighs, just above your knees.", "Stand facing a step or platform with your feet hip-width apart.", "Step up onto the platform with your right foot, pushing through your heel.", "Extend your left leg behind you, keeping it straight.", "Lower your left foot back down to the ground.", "Repeat with your left foot stepping up onto the platform.", "Continue alternating legs for the desired number of repetitions."]', '["Coloca una banda alrededor de los muslos, justo por encima de las rodillas.", "Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.", "Sube a la plataforma con el pie derecho, empujando con el talón.", "Extiende la pierna izquierda hacia atrás, manteniéndola recta.", "Baja el pie izquierdo de nuevo hasta el suelo.", "Repite subiendo a la plataforma con el pie izquierdo.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Step-Up con Barra', 'barbell-step-up.gif', 'upper legs', '["Stand in front of a bench or step with a barbell resting on your upper back.", "Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.", "Push through your heel and step up onto the bench or step, fully extending your hip and knee.", "Pause briefly at the top, then lower yourself back down to the starting position.", "Repeat with the opposite leg.", "Continue alternating legs for the desired number of repetitions."]', '["Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda.", "Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie.", "Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla.", "Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial.", "Repite con la pierna contraria.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Step-Up con Zancada con Mancuernas', 'dumbbell-step-up-lunge.gif', 'upper legs', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.", "Place your right foot on the step, ensuring your entire foot is on the surface.", "Push through your right heel and lift your body up onto the step, bringing your left foot up as well.", "Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.", "Repeat the movement, alternating which foot you step up with each time.", "Continue for the desired number of repetitions."]', '["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados.", "Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie.", "Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba.", "Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón.", "Repite el movimiento, alternando el pie con el que subes cada vez.", "Continúa durante el número de repeticiones deseado."]'),
  ('Tabla de Equilibrio', 'balance-board.gif', 'upper legs', '["Place the balance board on a flat surface.", "Step onto the balance board with one foot, ensuring it is centered.", "Slowly shift your weight onto the foot on the balance board, keeping your core engaged.", "Maintain your balance and stability as you hold the position for a desired amount of time.", "Repeat the exercise with the other foot."]', '["Coloca la tabla de equilibrio sobre una superficie plana.", "Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.", "Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.", "Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.", "Repite el ejercicio con el otro pie."]'),
  ('Tirón de Arrancada con Barra', 'snatch-pull.gif', 'upper legs', '["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.", "Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.", "Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.", "As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.", "As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.", "Catch the barbell overhead with your arms fully extended and your knees bent.", "Stand up by extending your hips and knees, keeping the barbell overhead.", "Lower the barbell back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.", "Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono.", "Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.", "Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.", "Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda.", "Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas.", "Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza.", "Baja la barra de nuevo a la posición inicial invirtiendo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Toque de Puntas Circular con Brazos Abiertos', 'arms-apart-circular-toe-touch-male.gif', 'upper legs', '["Stand with your feet shoulder-width apart and arms extended to the sides.", "Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.", "As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.", "Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.", "Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.", "Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.", "Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Toque de Puntas Circular con Manos Juntas', 'hands-clasped-circular-toe-touch-male.gif', 'upper legs', '["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las manos entrelazadas frente al pecho.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Baja las manos hacia los dedos de los pies con un movimiento circular, llegando tan lejos como puedas sin forzar.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Toque de Puntas de Pie', 'basic-toe-touch-male.gif', 'upper legs', '["Stand with your feet shoulder-width apart and your arms by your sides.", "Bend forward at the waist, keeping your back straight and your knees slightly bent.", "Reach down towards your toes with your hands, keeping your legs as straight as possible.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Volteo de Neumático', 'tire-flip.gif', 'upper legs', '["Stand with your feet shoulder-width apart, facing the tire.", "Bend your knees and hinge at the hips, lowering into a squat position.", "Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.", "Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.", "As the tire flips over, use your upper body strength to guide it and maintain control.", "Once the tire is fully flipped, quickly step back and reset your stance.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático.", "Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla.", "Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti.", "Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo.", "Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control.", "Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura.", "Repite el número de repeticiones deseado."]'),
  ('Zancada al Frente', 'forward-lunge-male.gif', 'upper legs', '["Stand with your feet hip-width apart and hands on your hips.", "Take a big step forward with your right foot, lowering your body into a lunge position.", "Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.", "Push off with your right foot and return to the starting position.", "Repeat with your left leg, alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.", "Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.", "Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo.", "Empuja con el pie derecho y vuelve a la posición inicial.", "Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."]'),
  ('Zancada al Frente Contralateral con Mancuerna', 'dumbbell-contralateral-forward-lunge.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, keeping your back straight and core engaged.", "Lower your body by bending both knees until your right thigh is parallel to the ground.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Alternate legs for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Da un paso adelante con el pie derecho, manteniendo la espalda recta y el core activado.", "Baja el cuerpo flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo.", "Empuja con el talón derecho para regresar a la posición inicial.", "Repite con la pierna izquierda.", "Alterna las piernas el número de repeticiones deseado."]'),
  ('Zancada con Balanceo de Peso', 'weighted-lunge-with-swing.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a weight in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge forward, swing the weights forward and upward, keeping your arms straight.", "Push off with your right foot and return to the starting position, swinging the weights back down.", "Repeat with your left foot and continue alternating legs for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano.", "Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.", "Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos.", "Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo.", "Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado."]'),
  ('Zancada con Estiramiento y Disco', 'weighted-stretch-lunge.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Take a step forward with your right foot, keeping your back straight.", "Lower your body by bending your knees until your right thigh is parallel to the ground.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Continue alternating legs for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Da un paso adelante con el pie derecho, manteniendo la espalda recta.", "Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo.", "Empuja con el talón derecho para regresar a la posición inicial.", "Repite con la pierna izquierda.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Zancada con Mancuernas', 'dumbbell-lunge.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "Keep your back straight and your chest up as you lower your body.", "Push through your right heel to return to the starting position.", "Repeat with your left leg.", "Alternate legs for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.", "Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo.", "Empuja con el talón derecho para regresar a la posición inicial.", "Repite con la pierna izquierda.", "Alterna las piernas el número de repeticiones deseado."]'),
  ('Zancada con Pase de Kettlebell', 'kettlebell-lunge-pass-through.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.", "Take a step forward with your right foot, lowering your body into a lunge position.", "As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.", "Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.", "Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.", "Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos.", "Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.", "Mientras avanzas en la zancada, pasa la pesa rusa por debajo del muslo derecho y trasládala a la mano izquierda.", "Empuja con el pie derecho para volver a la posición inicial, mientras pasas la pesa rusa de vuelta a la mano derecha al mismo tiempo.", "Repite la zancada en el lado opuesto, pasando la pesa rusa por debajo del muslo izquierdo.", "Continúa alternando zancadas y pasando la pesa rusa entre las manos durante el número de repeticiones deseado."]'),
  ('Zancada de Velocista en Máquina Smith', 'smith-sprint-lunge.gif', 'upper legs', '["Set up the smith machine with the barbell at hip height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.", "Bend your left knee and lower your body into a lunge position, keeping your back straight.", "Push through your left heel to return to the starting position.", "Repeat on the other side, stepping back with your left foot.", "Continue alternating sides for the desired number of repetitions."]', '["Configura la máquina Smith con la barra a la altura de la cadera.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella.", "Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta.", "Empuja con el talón izquierdo para volver a la posición inicial.", "Repite del otro lado, dando un paso hacia atrás con el pie izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Zancada Hacia Atrás con Mancuernas', 'dumbbell-rear-lunge.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step backward with your right foot, lowering your body into a lunge position.", "Bend your left knee and lower your body until your left thigh is parallel to the ground.", "Pause for a moment, then push through your left heel to return to the starting position.", "Repeat on the other side, stepping back with your left foot."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Da un paso hacia atrás con el pie derecho, bajando el cuerpo a una posición de zancada.", "Flexiona la rodilla izquierda y baja el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.", "Haz una pausa por un momento, luego empuja con el talón izquierdo para volver a la posición inicial.", "Repite del otro lado, dando un paso hacia atrás con el pie izquierdo."]'),
  ('Abdominal (Sit-Up)', 'sit-up-v-2.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal Asistido (con Compañero)', 'assisted-sit-up.gif', 'waist', '["Sit on the edge of a bench or have someone hold your feet down.", "Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco o pide a alguien que te sujete los pies.", "Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal Bicicleta', 'air-bike.gif', 'waist', '["Lie flat on your back with your hands placed behind your head.", "Lift your legs off the ground and bend your knees at a 90-degree angle.", "Bring your right elbow towards your left knee while simultaneously straightening your right leg.", "Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.", "Continue alternating sides in a pedaling motion for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.", "Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.", "Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.", "Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.", "Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado."]'),
  ('Abdominal Completo con Brazos por Encima de la Cabeza', 'arms-overhead-full-sit-up-male.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms overhead, keeping them straight.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Extiende los brazos por encima de la cabeza, manteniéndolos rectos.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Brazos Cruzados en el Pecho', 'sit-up-with-arms-on-chest.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Cross your arms over your chest.", "Engaging your abs, lift your upper body off the ground towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Cruza los brazos sobre el pecho.", "Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Brazos Rectos', 'flexion-leg-sit-up-straight-arm.gif', 'waist', '["Lie flat on your back with your legs extended and arms straight above your head.", "Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.", "Reach your hands towards your toes as you lift your upper body and legs.", "Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con las piernas extendidas y los brazos rectos por encima de la cabeza.", "Activando el abdomen, levanta la parte superior del cuerpo del suelo mientras al mismo tiempo levantas las piernas hacia el pecho.", "Extiende las manos hacia los dedos de los pies mientras levantas la parte superior del cuerpo y las piernas.", "Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Empuje con Banda Elástica', 'band-push-sit-up.gif', 'waist', '["Attach the band securely to a stable anchor point.", "Lie flat on your back with your knees bent and feet flat on the ground.", "Hold the band with both hands and extend your arms straight up towards the ceiling.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda de forma segura a un punto de anclaje estable.", "Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Giro en Banco Inclinado', 'incline-twisting-sit-up.gif', 'waist', '["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet secured under the foot pads.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body off the bench, curling forward.", "As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat the movement, this time twisting your torso to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo del banco, curvándote hacia adelante.", "Mientras te incorporas, gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el movimiento, esta vez girando el torso hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Abdominal con Press de Barra', 'barbell-press-sit-up.gif', 'waist', '["Lie flat on your back on a mat with your knees bent and feet flat on the ground.", "Hold the barbell with an overhand grip, resting it on your chest.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.", "Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Press de Disco (Otis-Up)', 'otis-up.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal con Rodillas Flexionadas', 'flexion-leg-sit-up-bent-knee.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.", "Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Al mismo tiempo, levanta las piernas del suelo, doblando las rodillas y llevándolas hacia el pecho.", "Haz una pausa breve en la parte superior, luego baja lentamente la parte superior del cuerpo y las piernas a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal de 3/4', '3-4-sit-up.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal Declinado', 'decline-sit-up.gif', 'waist', '["Lie on a decline bench with your feet secured and your knees bent.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body off the bench, curling forward towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo del banco, flexionándote hacia adelante en dirección a las rodillas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal Declinado con Disco', 'weighted-decline-sit-up.gif', 'waist', '["Lie flat on a decline bench with your feet secured under the foot pads.", "Place your hands behind your head or across your chest.", "Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal en Navaja (Jackknife)', 'jackknife-sit-up.gif', 'waist', '["Lie flat on your back with your legs extended and your arms overhead.", "Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con las piernas extendidas y los brazos por encima de la cabeza.", "Activa el core y levanta las piernas y la parte superior del cuerpo al mismo tiempo, llevando las manos hacia los dedos de los pies.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal en Navaja con Banda Elástica', 'band-jack-knife-sit-up.gif', 'waist', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.", "Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Abdominal Janda', 'janda-sit-up.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Balanceo Colgado con Piernas Rectas', 'arm-slingers-hanging-straight-legs.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your legs straight down.", "Engage your core and lift your legs up in front of you until they are parallel to the ground.", "Hold for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo.", "Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.", "Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Balanceo Colgado con Rodillas Flexionadas', 'arm-slingers-hanging-bent-knee-legs.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.", "Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.", "Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Bandera Humana', 'flag.gif', 'waist', '["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.", "Engage your core and lift your legs off the ground, keeping them straight.", "Using your core and upper body strength, raise your legs until they are parallel to the ground.", "Hold this position for as long as you can, maintaining a straight body line.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza sujetando un poste vertical con ambas manos, palmas una frente a la otra, y los brazos completamente extendidos.", "Activa el core y levanta las piernas del suelo, manteniéndolas rectas.", "Usando la fuerza del core y de la parte superior del cuerpo, levanta las piernas hasta que queden paralelas al suelo.", "Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Capullo (Crunch Completo)', 'cocoons.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Caída Abdominal en Suspensión (TRX)', 'suspended-abdominal-fallout.gif', 'waist', '["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.", "Stand facing away from the anchor point and hold the handles with your arms extended in front of you.", "Lean forward at the waist, keeping your body straight and your core engaged.", "Lower your body as far as you can while maintaining control and tension in your abs.", "Pause for a moment at the bottom, then slowly raise your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura.", "Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti.", "Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado.", "Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen.", "Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Codo a Rodilla', 'elbow-to-knee.gif', 'waist', '["Start by lying flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.", "At the same time, bring your left knee towards your right elbow, creating a twisting motion.", "Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.", "Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.", "Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial.", "Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Codo a Rodilla Tumbado', 'lying-elbow-to-knee.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.", "At the same time, extend your right leg straight out and lift it off the ground.", "Pause for a moment, then return to the starting position.", "Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.", "Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch Bicicleta con Banda Elástica', 'band-bicycle-crunch-0972.gif', 'waist', '["Lie flat on your back with your hands behind your head and your knees bent.", "Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.", "Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.", "Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.", "Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.", "Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.", "Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Disco', 'weighted-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Hold a weight plate or dumbbell on your chest.", "Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Sostén un disco de peso o una mancuerna sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Disco sobre Fitball', 'weighted-overhead-crunch-on-stability-ball.gif', 'waist', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a weight plate or dumbbell with both hands and extend your arms overhead.", "Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly lower your torso back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza.", "Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.", "Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Elevación de Piernas en Máquina', 'lever-seated-leg-raise-crunch.gif', 'waist', '["Sit on the leverage machine with your back against the backrest and your feet on the footrests.", "Grasp the handles or sidebars for stability.", "Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.", "Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la máquina de palanca con la espalda apoyada en el respaldo y los pies sobre los apoyapiés.", "Sujeta las asas o las barras laterales para mayor estabilidad.", "Activa el abdomen y eleva lentamente las piernas hacia el pecho, mientras curvas el torso hacia adelante al mismo tiempo.", "Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas y el torso a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Giro de Pie con Banda Elástica', 'band-standing-twisting-crunch.gif', 'waist', '["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.", "Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.", "Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.", "Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.", "Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch con Giro de Rodillas con Banda Elástica', 'band-kneeling-twisting-crunch.gif', 'waist', '["Attach the band to a sturdy anchor point at waist height.", "Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.", "Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.", "Pause for a moment, then slowly return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.", "Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.", "Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch con Manos por Encima de la Cabeza', 'crunch-hands-overhead.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms straight above your head.", "Engaging your abs, lift your upper body off the ground, curling forward towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Extiende los brazos rectos por encima de la cabeza.", "Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Piernas Abiertas', 'groin-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch con Toque de Rodilla', 'knee-touch-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.", "Return to the starting position and repeat, this time reaching your left hand towards your right knee.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda.", "Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch Cruzado', 'cross-body-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat on the other side, bringing your left elbow towards your right knee.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.", "Repite el número de repeticiones deseado."]'),
  ('Crunch de Pie con Banda Elástica', 'band-standing-crunch-1005.gif', 'waist', '["Attach the band to a sturdy anchor point at waist height.", "Stand facing away from the anchor point with your feet shoulder-width apart.", "Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.", "Engage your abs and slowly crunch forward, bringing your chest towards your knees.", "Pause for a moment at the top of the crunch, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.", "Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.", "Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.", "Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.", "Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch de Pie en Polea', 'cable-standing-crunch.gif', 'waist', '["Attach a cable handle to a high pulley and stand facing away from the machine.", "Hold the handle with both hands and place it behind your head, keeping your elbows bent.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina.", "Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados.", "Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos.", "Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch de Pie en Polea con Cuerda', 'cable-standing-crunch-with-rope-attachment.gif', 'waist', '["Attach a rope to a cable machine at chest height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Hold the rope with both hands and bring it behind your head, keeping your elbows bent.", "Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.", "Pause for a moment at the top of the crunch, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una máquina de cable a la altura del pecho.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados.", "Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas.", "Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch de Rana', 'frog-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch de Rodillas en Polea', 'cable-kneeling-crunch-0175.gif', 'waist', '["Attach a rope handle to a high pulley and kneel down facing away from the machine.", "Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.", "Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina.", "Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados.", "Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Declinado', 'decline-crunch.gif', 'waist', '["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body towards your knees, curling your torso.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y las rodillas flexionadas en un ángulo de 90 grados.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Encogido (Tuck Crunch)', 'tuck-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.", "Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.", "Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Inverso con Rodillo', 'roller-reverse-crunch.gif', 'waist', '["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.", "Place the roller between your feet and grip it with your toes.", "Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti.", "Coloca el rodillo entre los pies y sujétalo con los dedos de los pies.", "Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo.", "Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Inverso en Polea', 'cable-reverse-crunch.gif', 'waist', '["Attach a cable to a low pulley and lie down facing up on a mat.", "Hold the cable with both hands and extend your arms straight up towards the ceiling.", "Bend your knees and lift your legs up, bringing your thighs towards your chest.", "While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete.", "Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo.", "Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho.", "Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Inverso en Suspensión (TRX)', 'suspended-reverse-crunch.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.", "Pause for a moment at the top, then slowly lower your knees back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica.", "Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Inverso Encogido en Polea', 'cable-tuck-reverse-crunch.gif', 'waist', '["Attach a cable to a low pulley and lie down on a mat facing up.", "Hold the cable with both hands and extend your arms straight up above your chest.", "Bend your knees and lift your legs up, bringing your knees towards your chest.", "At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.", "Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla.", "Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho.", "Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho.", "Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo.", "Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Lateral de Pie en Polea', 'cable-side-crunch.gif', 'waist', '["Attach a cable handle to a low pulley and stand sideways to the machine.", "Grasp the handle with the hand furthest from the machine and place your other hand on your hip.", "Keep your feet shoulder-width apart and your knees slightly bent.", "With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina.", "Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera.", "Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.", "Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Crunch Lateral en Polea sobre Bosu', 'cable-side-bend-crunch-bosu-ball.gif', 'waist', '["Stand with your feet shoulder-width apart, holding a cable handle in one hand.", "Place the other hand on your hip.", "Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano.", "Coloca la otra mano en la cadera.", "Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta.", "Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Crunch Lateral Sentado en la Pared', 'seated-side-crunch-wall.gif', 'waist', '["Sit on the floor with your back against a wall and your legs extended in front of you.", "Bend your knees and place your feet flat on the floor, hip-width apart.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and lean to one side, bringing your elbow towards your hip.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti.", "Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch Negativo', 'negative-crunch.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Oblicuo con Pies en Banco', 'oblique-crunch-v-2.gif', 'waist', '["Lie on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.", "Pause for a moment, then lower your shoulder blades back down to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.", "Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Crunch Oblicuo en el Suelo', 'oblique-crunches-floor.gif', 'waist', '["Lie on your back with your knees bent and feet flat on the floor.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.", "Pause for a moment, then lower your shoulder blades back down to the floor.", "Repeat on the other side, alternating sides with each repetition."]', '["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.", "Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.", "Repite hacia el otro lado, alternando los lados en cada repetición."]'),
  ('Crunch Sentado en Máquina con Almohadilla de Pecho', 'lever-seated-crunch-chest-pad.gif', 'waist', '["Adjust the seat height and chest pad position according to your comfort.", "Sit on the machine with your back against the chest pad and your feet flat on the floor.", "Grasp the handles or side bars for stability.", "Engage your abs and slowly lean back, allowing the chest pad to move with you.", "Pause for a moment at the maximum contraction, feeling the tension in your abs.", "Slowly return to the starting position by contracting your abs and pulling yourself back up.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y la posición de la almohadilla para el pecho según tu comodidad.", "Siéntate en la máquina con la espalda apoyada en la almohadilla para el pecho y los pies planos en el suelo.", "Sujeta las asas o las barras laterales para mayor estabilidad.", "Activa el abdomen y reclínate lentamente hacia atrás, permitiendo que el respaldo se mueva contigo.", "Haz una pausa en la contracción máxima, sintiendo la tensión en el abdomen.", "Vuelve lentamente a la posición inicial contrayendo el abdomen y tirando de tu cuerpo hacia arriba.", "Repite el número de repeticiones deseado."]'),
  ('Crunch Sentado en Polea', 'cable-seated-crunch.gif', 'waist', '["Sit on a cable machine with your feet flat on the ground and your knees bent.", "Hold the cable handle with both hands and position it behind your head.", "Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas.", "Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza.", "Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.", "Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch sobre Fitball', 'crunch-on-stability-ball.gif', 'waist', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.", "Place your hands behind your head or across your chest.", "Engage your abs and lift your upper body towards your knees, curling your torso forward.", "Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.", "Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante.", "Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch sobre Fitball con Brazos Rectos', 'crunch-on-stability-ball-arms-straight.gif', 'waist', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.", "Place your hands behind your head or cross them over your chest.", "Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Crunch sobre Fitball de Recorrido Completo', 'stability-ball-crunch-full-range-hands-behind-head.gif', 'waist', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.", "Pause for a moment at the top, then slowly lower your upper body back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Cuarto de Abdominal', 'quarter-sit-up.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl-Up (Crunch Corto)', 'curl-up.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Gorila (con Elevación de Rodillas)', 'gorilla-chin.gif', 'waist', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.", "Hang from the bar with your arms fully extended and your palms facing away from you.", "Engage your core and pull your body up towards the bar, bringing your chin above the bar.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra de dominadas con agarre prono, ligeramente más ancho que la altura de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y las palmas hacia afuera.", "Activa el core y tira del cuerpo hacia la barra, llevando la barbilla por encima de la barra.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Cadera en Máquina Smith', 'smith-hip-raise.gif', 'waist', '["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.", "Place your hands on the barbell, slightly wider than shoulder-width apart.", "Engage your core and glutes, then push through your heels to raise your hips off the ground.", "Continue lifting until your body forms a straight line from your knees to your shoulders.", "Hold for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros.", "Coloca las manos en la barra, un poco más separadas que el ancho de los hombros.", "Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo.", "Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Cadera en Plancha (Butt-Ups)', 'butt-ups.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides, palms facing down.", "Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.", "At the top of the movement, squeeze your abs and pause for a moment.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos a los lados, con las palmas hacia abajo.", "Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.", "En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Cadera Tumbado (Bottoms-Up)', 'bottoms-up.gif', 'waist', '["Lie flat on your back with your legs extended and your arms by your sides.", "Bend your knees and bring them towards your chest, keeping your feet off the ground.", "Engaging your abs, lift your hips off the ground, bringing your knees towards your head.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo.", "Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Cadera Tumbado con Rodillas Flexionadas', 'hip-raise-bent-knee.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides, palms facing down.", "Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos a los lados, con las palmas hacia abajo.", "Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Alterna Sentado con Barra', 'barbell-sitted-alternate-leg-raise.gif', 'waist', '["Sit on a bench with your back straight and hold a barbell across your thighs.", "Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.", "Lower the raised leg back down and repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.", "Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo.", "Baja la pierna elevada y repite con la otra pierna.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Elevación de Piernas con Giro en Paralelas', 'twisted-leg-raise.gif', 'waist', '["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your abs and lift both legs off the ground, keeping them straight.", "As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat the movement, this time twisting your hips to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Coloca las manos debajo de los glúteos como apoyo.", "Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas.", "Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el movimiento, esta vez girando las caderas hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Elevación de Piernas Rectas con Giro Colgado', 'hanging-straight-twisting-leg-hip-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your legs straight.", "Engage your core and lift your legs up towards your chest, keeping them straight.", "Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.", "Pause for a moment, then return to the starting position.", "Repeat the movement, but this time twist your hips to the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas rectas.", "Activa el core y levanta las piernas hacia el pecho, manteniéndolas rectas.", "Cuando las piernas queden paralelas al suelo, gira las caderas hacia un lado, llevando las piernas hacia ese lado.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite el movimiento, pero esta vez gira las caderas hacia el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Elevación de Piernas Rectas en Silla Romana', 'captains-chair-straight-leg-raise.gif', 'waist', '["Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.", "Keep your upper body stable and your back straight.", "Engage your abs and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas.", "Mantén la parte superior del cuerpo estable y la espalda recta.", "Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.", "Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Rectas Tumbado con Banda Elástica', 'band-lying-straight-leg-raise.gif', 'waist', '["Lie flat on your back with your legs straight and your feet together.", "Place the band around the arches of your feet and hold the ends of the band with your hands.", "Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas rectas y los pies juntos.", "Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.", "Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Rectas y Cadera Colgado', 'hanging-straight-leg-hip-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Tumbado con Empuje (con Compañero)', 'assisted-lying-leg-raise-with-throw-down.gif', 'waist', '["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your core and lift your legs off the ground, keeping them straight.", "Raise your legs until they are perpendicular to the ground.", "Lower your legs back down to the starting position.", "Simultaneously, throw your legs down towards the ground, keeping them straight.", "Raise your legs back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Coloca las manos debajo de los glúteos como apoyo.", "Activa el core y levanta las piernas del suelo, manteniéndolas rectas.", "Eleva las piernas hasta que queden perpendiculares al suelo.", "Baja las piernas de vuelta a la posición inicial.", "Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.", "Eleva las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas Tumbado con Empuje Lateral (con Compañero)', 'assisted-lying-leg-raise-with-lateral-throw-down.gif', 'waist', '["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your abs and lift your legs off the ground, keeping them straight.", "While keeping your legs together, lower them to one side until they are a few inches above the ground.", "Pause for a moment, then lift your legs back to the starting position.", "Repeat the movement to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Coloca las manos debajo de los glúteos como apoyo.", "Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.", "Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.", "Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.", "Repite el movimiento hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Elevación de Piernas y Cadera Colgado', 'hanging-leg-hip-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las piernas flexionando las caderas y las rodillas hasta que los muslos queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas y Cadera Colgado con Peso', 'weighted-hanging-leg-hip-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or slightly higher.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.", "Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas y Cadera en Banco', 'lying-leg-hip-raise.gif', 'waist', '["Lie flat on your back with your legs extended and your arms by your sides.", "Place your hands under your glutes for support.", "Engage your core and lift your legs off the ground, raising them towards the ceiling.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Coloca las manos debajo de los glúteos como apoyo.", "Activa el core y levanta las piernas del suelo, elevándolas hacia el techo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Piernas y Cadera en Banco Inclinado', 'incline-leg-hip-raise-leg-straight.gif', 'waist', '["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.", "Place your hands on the sides of the bench for support.", "Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco inclinado con la espalda apoyada plana en el banco y las piernas extendidas rectas frente a ti.", "Coloca las manos a los lados del banco para apoyarte.", "Activando el abdomen, levanta las piernas del banco, elevándolas tan alto como puedas mientras las mantienes rectas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Rodillas Colgado Asistida', 'assisted-hanging-knee-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.", "Pause for a moment at the top of the movement, squeezing your abs.", "Slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.", "Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.", "Baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Rodillas Colgado Asistida con Empuje', 'assisted-hanging-knee-raise-with-throw-down.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees towards your chest, keeping your legs together.", "Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.", "Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.", "Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.", "Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado."]'),
  ('Elevación de Rodillas en Paralelas', 'vertical-leg-raise-on-parallel-bars.gif', 'waist', '["Hang from the parallel bars with your arms fully extended and your body straight.", "Engage your core and lift your legs up in front of you, keeping them straight.", "Continue lifting until your legs are parallel to the ground or slightly higher.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto.", "Activa el core y levanta las piernas frente a ti, manteniéndolas rectas.", "Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Rodillas Lateral en Paralelas', 'side-hip-on-parallel-bars.gif', 'waist', '["Stand between two parallel bars with your feet shoulder-width apart.", "Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.", "Engage your abs and slowly lift your legs to the side, keeping them straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros.", "Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos.", "Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Rodillas Oblicua Colgado', 'hanging-oblique-knee-raise.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat on the other side, twisting your torso in the opposite direction.", "Continue alternating sides for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las rodillas hacia el pecho, girando el torso hacia un lado mientras lo haces.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite hacia el otro lado, girando el torso en la dirección opuesta.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Elevación de Rodillas Sentado en Banco', 'seated-leg-raise.gif', 'waist', '["Sit on a flat bench with your back straight and your feet flat on the ground.", "Place your hands on the sides of the bench for support.", "Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo.", "Coloca las manos a los lados del banco para apoyarte.", "Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimiento de Piernas en Banco Plano', 'leg-pull-in-flat-bench.gif', 'waist', '["Sit on a flat bench with your legs extended straight out in front of you.", "Place your hands on the bench beside your hips for support.", "Engage your abs and lift your legs off the ground, bringing your knees towards your chest.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco plano con las piernas extendidas rectas hacia adelante.", "Coloca las manos en el banco junto a las caderas para mayor apoyo.", "Activa el abdomen y levanta las piernas del suelo, llevando las rodillas hacia el pecho.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Encogimiento de Rodillas sobre Fitball', 'pull-in-on-stability-ball.gif', 'waist', '["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands on the sides of the stability ball for support.", "Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.", "Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados.", "Coloca las manos a los lados del balón de estabilidad para mayor apoyo.", "Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho.", "Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Escalador Cruzado en Puente', 'bridge-mountain-climber-cross-body.gif', 'waist', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.", "Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.", "Continue alternating sides, moving at a controlled pace.", "Keep your hips level and avoid lifting your hips too high or sagging them too low.", "Maintain a steady breathing pattern throughout the exercise.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo.", "Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho.", "Continúa alternando los lados, moviéndote a un ritmo controlado.", "Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo.", "Mantén un patrón de respiración constante durante todo el ejercicio.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Asistido de Recto Femoral Boca Abajo', 'assisted-prone-rectus-femoris-stretch.gif', 'waist', '["Lie face down on the ground with your legs straight.", "Bend your right knee and reach back with your right hand to grab your right foot or ankle.", "Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.", "Hold the stretch for 20-30 seconds.", "Release and repeat on the other side."]', '["Túmbate boca abajo en el suelo con las piernas rectas.", "Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.", "Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta y repite del otro lado."]'),
  ('Figura en 8 con Kettlebell', 'kettlebell-figure-8.gif', 'waist', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.", "As the kettlebell comes forward, pass it to the other hand between your legs.", "Continue passing the kettlebell between your legs in a figure 8 motion.", "Maintain a steady pace and engage your core throughout the exercise.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Pasa la pesa rusa entre las piernas, cambiándola de mano cuando llegue detrás de las piernas.", "Cuando la pesa rusa vuelva hacia adelante, pásala a la otra mano entre las piernas.", "Continúa pasando la pesa rusa entre las piernas con un movimiento en forma de ocho.", "Mantén un ritmo constante y activa el core durante todo el ejercicio.", "Repite el número de repeticiones deseado."]'),
  ('Flexión a Plancha Lateral', 'push-up-to-side-plank.gif', 'waist', '["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping your core engaged.", "Push back up to the starting position.", "Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.", "Hold the side plank position for a few seconds, then return to the starting position.", "Repeat the push-up and side plank on the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado.", "Empuja hacia arriba para volver a la posición inicial.", "Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo.", "Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial.", "Repite la flexión y la plancha lateral en el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión Lateral con Disco sobre Fitball', 'weighted-side-bend-on-stability-ball.gif', 'waist', '["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.", "Hold a weight in one hand and place your other hand on your hip.", "Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo.", "Sostén un peso en una mano y coloca la otra mano sobre la cadera.", "Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Flexión Lateral con Mancuerna', 'dumbbell-side-bend.gif', 'waist', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.", "Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano y dejando que cuelgue a tu costado.", "Manteniendo la espalda recta y el core activado, inclínate lentamente hacia el lado opuesto de la mancuerna, bajando el peso tanto como te sea posible con comodidad.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado y repite."]'),
  ('Flexión Lateral de Pie con Barra', 'barbell-side-bent-v-2.gif', 'waist', '["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.", "Keep your back straight and core engaged throughout the exercise.", "Slowly bend your torso to the right side, lowering the barbell towards your right knee.", "Pause for a moment, then return to the starting position.", "Repeat the movement on the left side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite el movimiento hacia el lado izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión Lateral en Banco a 45°', '45-side-bend.gif', 'waist', '["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.", "Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.", "Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Flexión Lateral en Polea', 'cable-side-bend.gif', 'waist', '["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.", "Keep your back straight and your core engaged.", "Slowly bend sideways at the waist, lowering the cable handle towards your knee.", "Pause for a moment, then return to the starting position.", "Repeat on the other side.", "Alternate sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano.", "Mantén la espalda recta y el core activado.", "Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite del otro lado.", "Alterna los lados durante el número de repeticiones deseado."]'),
  ('Front Lever', 'front-lever.gif', 'waist', '["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.", "Engage your core and pull your shoulder blades down and back.", "Bend your knees and tuck them towards your chest.", "Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.", "Hold this position for as long as you can, aiming for a full front lever position.", "To release, slowly lower your legs back down and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgado de una barra de dominadas con agarre prono, manos separadas a la altura de los hombros.", "Activa el core y lleva los omóplatos hacia abajo y atrás.", "Flexiona las rodillas y llévalas hacia el pecho.", "Al mismo tiempo, levanta las piernas y extiéndelas rectas frente a ti, manteniendo el cuerpo paralelo al suelo.", "Mantén esta posición todo el tiempo que puedas, intentando lograr una posición completa de palanca frontal.", "Para soltar, baja lentamente las piernas y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Giro Boca Abajo sobre Fitball', 'prone-twist-on-stability-ball.gif', 'waist', '["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.", "Place your hands behind your head or cross them over your chest.", "Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.", "Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.", "Pause for a moment, then return to the starting position.", "Repeat the rotation to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta.", "Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento.", "Haz una pausa breve y luego vuelve a la posición inicial.", "Repite la rotación hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro de Columna Sentado', 'spine-twist.gif', 'waist', '["Sit on the ground with your legs extended in front of you.", "Bend your knees and place your feet flat on the ground, hip-width apart.", "Place your hands behind your head with your elbows pointing outwards.", "Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the left side, bringing your left elbow towards your right knee.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.", "Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.", "Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro de Pie con Barra', 'barbell-standing-twist.gif', 'waist', '["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.", "Engage your core and keep your back straight throughout the exercise.", "Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the left side.", "Continue alternating twists for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo.", "Activa el core y mantén la espalda recta durante todo el ejercicio.", "Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo.", "Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.", "Repite el giro hacia el lado izquierdo.", "Continúa alternando los giros el número de repeticiones deseado."]'),
  ('Giro de Pie en Polea', 'cable-twist.gif', 'waist', '["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.", "Engage your core and twist your torso to the right, pulling the cable across your body.", "Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.", "Slowly return to the starting position, resisting the cable''s pull.", "Repeat the movement to the left side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.", "Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados.", "Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo.", "Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos.", "Regresa lentamente a la posición inicial, resistiendo la tracción del cable.", "Repite el movimiento hacia el lado izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro de Rodillas en Máquina', 'lever-kneeling-twist.gif', 'waist', '["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.", "Grasp the handles or the sides of the machine for stability.", "Keeping your core engaged, twist your torso to one side as far as comfortably possible.", "Pause for a moment, then slowly return to the starting position.", "Repeat the twist to the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con las rodillas apoyadas en las almohadillas y la parte superior del cuerpo mirando hacia adelante.", "Sujeta las asas o los lados de la máquina para mayor estabilidad.", "Manteniendo el core activado, gira el torso hacia un lado tanto como sea cómodamente posible.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el giro hacia el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Ruso con Balón Medicinal', 'weighted-russian-twist.gif', 'waist', '["Sit on the ground with your knees bent and your feet flat on the floor.", "Hold a weight or medicine ball with both hands in front of your chest.", "Lean back slightly, keeping your back straight and your core engaged.", "Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.", "Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.", "Sostén un peso o un balón medicinal con ambas manos frente al pecho.", "Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado.", "Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho.", "Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Ruso con Disco y Piernas Elevadas', 'weighted-russian-twist-legs-up.gif', 'waist', '["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.", "Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.", "Lean back slightly to engage your core muscles.", "Twist your torso to the right, bringing the weight towards the ground on your right side.", "Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo, manteniendo las piernas juntas.", "Sostén el peso con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.", "Inclínate ligeramente hacia atrás para activar los músculos del core.", "Gira el torso hacia la derecha, llevando el peso hacia el suelo a tu lado derecho.", "Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el suelo a tu lado izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Ruso con Pase de Balón Medicinal', 'assisted-motion-russian-twist.gif', 'waist', '["Sit on the ground with your knees bent and feet flat on the floor.", "Hold the medicine ball with both hands in front of your chest.", "Lean back slightly, engaging your abs and keeping your back straight.", "Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.", "Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.", "Sostén el balón medicinal con ambas manos frente al pecho.", "Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.", "Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.", "Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Sentado con Banda Elástica', 'band-seated-twist.gif', 'waist', '["Sit on the ground with your legs extended in front of you and your back straight.", "Wrap the band around your waist and hold the ends with both hands.", "Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.", "Pause for a moment at the end of the twist, then slowly return to the starting position.", "Repeat the twist to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.", "Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.", "Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.", "Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.", "Repite el giro hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Sentado con Barra', 'barbell-seated-twist.gif', 'waist', '["Sit on a flat bench with your feet flat on the ground and your knees bent.", "Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.", "Engage your core and slowly twist your torso to one side, keeping your back straight.", "Pause for a moment at the end of the twist, then slowly rotate back to the starting position.", "Repeat the twist to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.", "Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.", "Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.", "Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.", "Repite el giro hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Sentado con Disco sobre Fitball', 'weighted-seated-twist-on-stability-ball.gif', 'waist', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a weight plate or dumbbell with both hands close to your chest.", "Engage your core and slowly rotate your torso to one side, keeping your hips stable.", "Pause for a moment at the end of the rotation, then slowly return to the starting position.", "Repeat the rotation to the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho.", "Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables.", "Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.", "Repite la rotación hacia el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giro Sentado en Polea', 'cable-seated-twist.gif', 'waist', '["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.", "Hold the cable handle with both hands and extend your arms straight in front of you.", "Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.", "Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.", "Repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas.", "Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.", "Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo.", "Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial.", "Repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Giros Rusos en Polea sobre Fitball', 'cable-russian-twists-on-stability-ball-0211.gif', 'waist', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold the cable handle with both hands and extend your arms straight out in front of you.", "Lean back slightly while keeping your back straight and your core engaged.", "Twist your torso to the right, bringing the cable handle towards your right hip.", "Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.", "Continue alternating twists for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti.", "Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.", "Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha.", "Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda.", "Continúa alternando los giros el número de repeticiones deseado."]'),
  ('Golpe con Mazo en Neumático', 'sledge-hammer.gif', 'waist', '["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.", "Engage your core and keep your back straight.", "Swing the sledge hammer down towards the ground, using your core and upper body strength.", "As you swing down, pivot your hips and transfer the force to the hammer.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos.", "Activa el core y mantén la espalda recta.", "Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo.", "Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo.", "Repite el número de repeticiones deseado."]'),
  ('Gusano (Inchworm)', 'inchworm.gif', 'waist', '["Start in a standing position with your feet hip-width apart.", "Bend forward at the waist and place your hands on the ground in front of you.", "Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.", "Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.", "Once your hands reach your feet, stand back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de las caderas.", "Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.", "Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.", "Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.", "Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Inclinación Pélvica Tumbado', 'pelvic-tilt.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides.", "Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.", "Hold this position for a few seconds, focusing on contracting your abs.", "Release the tilt and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos a los lados del cuerpo.", "Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.", "Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.", "Deshaz la inclinación y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Landmine 180', 'landmine-180.gif', 'waist', '["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.", "Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.", "As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.", "Continue this twisting motion, alternating sides, for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente al pecho.", "Flexiona ligeramente las rodillas y rota el torso hacia la derecha, llevando la barra hacia la cadera derecha.", "Cuando llegues a la parte baja del movimiento, invierte rápidamente el movimiento y rota el torso hacia la izquierda, llevando la barra hacia arriba y a través del cuerpo en dirección al hombro izquierdo.", "Continúa este movimiento de giro, alternando lados, durante el número de repeticiones deseado."]'),
  ('Lanzador de Hechizos con Mancuernas (Spell Caster)', 'spell-caster.gif', 'waist', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Bend your knees slightly and hinge forward at the waist, keeping your back straight.", "Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.", "Return to the starting position and repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta.", "Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces.", "Regresa a la posición inicial y repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Leñador de Abajo hacia Arriba en Polea', 'cable-standing-lift.gif', 'waist', '["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with both hands and position it at waist height.", "Engage your core and maintain a straight back throughout the exercise.", "Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.", "Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura.", "Activa el core y mantén la espalda recta durante todo el ejercicio.", "Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso.", "Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Maltese Completo', 'full-maltese.gif', 'waist', '["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.", "Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.", "Engage your core and hold this position for a few seconds.", "Return to the starting position by pushing through your feet and standing back up.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos rectos hacia los lados.", "Inclínate lentamente hacia adelante, manteniendo los brazos rectos, hasta que la parte superior del cuerpo quede paralela al suelo.", "Activa el core y mantén esta posición durante unos segundos.", "Regresa a la posición inicial empujando con los pies y volviendo a ponerte de pie.", "Repite el número de repeticiones deseado."]'),
  ('Maltese con Piernas Abiertas', 'straddle-maltese.gif', 'waist', '["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.", "Spread your legs wide apart, forming a straddle position.", "Engage your core and slowly lower your body until your arms are parallel to the ground.", "Hold this position for a few seconds, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta.", "Separa bien las piernas, formando una posición a horcajadas.", "Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo.", "Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Medio Abdominal', 'half-sit-up-male.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Medio Abdominal con Manos tras la Cabeza', 'prisoner-half-sit-up-male.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head with your elbows pointing outwards.", "Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.", "Pause for a moment at the top, then slowly lower your upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.", "Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Molino Avanzado con Kettlebell', 'kettlebell-advanced-windmill.gif', 'waist', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.", "Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.", "Rotate your left foot slightly to the right, and shift your weight onto your left leg.", "Bend your left knee and hinge at the hip, lowering your torso towards the left side.", "Keep your right arm extended overhead and your eyes on the kettlebell.", "As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.", "Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.", "Pause for a moment, then engage your core and push through your left heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.", "Sostén una pesa rusa en la mano derecha, con el brazo extendido por encima de la cabeza y la palma hacia adelante.", "Gira el pie izquierdo ligeramente hacia la derecha y traslada el peso hacia la pierna izquierda.", "Dobla la rodilla izquierda y flexiona la cadera, bajando el torso hacia el lado izquierdo.", "Mantén el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.", "Mientras bajas el torso, permite que la pierna derecha se enderece y que el pie derecho gire ligeramente.", "Baja el torso hasta sentir un estiramiento en el isquiotibial izquierdo y que el brazo derecho apunte hacia el suelo.", "Haz una pausa breve, luego activa el core y empuja con el talón izquierdo para regresar a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Molino con Kettlebell', 'kettlebell-windmill.gif', 'waist', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.", "Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.", "Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.", "Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.", "Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en la mano derecha por encima de la cabeza.", "Rota el pie izquierdo hacia afuera unos 45 grados y mantén el pie derecho apuntando hacia adelante.", "Inclina el torso hacia el lado izquierdo, manteniendo el brazo derecho extendido por encima de la cabeza y la mirada en la pesa rusa.", "Baja el torso tanto como puedas mientras mantienes el brazo derecho recto y el brazo izquierdo extendido hacia el lado.", "Haz una pausa breve, luego vuelve a la posición inicial empujando con el pie derecho y activando los oblicuos.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Molino Doble con Kettlebells', 'kettlebell-double-windmill.gif', 'waist', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.", "Extend your right arm overhead, keeping your eyes on the kettlebell.", "Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.", "Bend at the waist to the left, keeping your right arm extended overhead.", "Lower the kettlebell towards the ground, reaching towards your left foot.", "Pause for a moment, then engage your core and push through your right foot to return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.", "Extiende el brazo derecho por encima de la cabeza, manteniendo la mirada en la pesa rusa.", "Rota el pie izquierdo 45 grados hacia la izquierda y el pie derecho 90 grados hacia la derecha.", "Flexiona la cintura hacia la izquierda, manteniendo el brazo derecho extendido por encima de la cabeza.", "Baja la pesa rusa hacia el suelo, extendiéndote hacia el pie izquierdo.", "Haz una pausa breve, luego activa el core y empuja con el pie derecho para volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Pallof Press Vertical con Banda Elástica', 'band-vertical-pallof-press.gif', 'waist', '["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.", "Hold the band with both hands and step away from the anchor point, creating tension in the band.", "Position yourself perpendicular to the anchor point, with your side facing the band.", "Extend your arms straight out in front of you, keeping your hands at chest height.", "Engage your core and press the band away from your chest, fully extending your arms.", "Hold the position for a few seconds, then slowly bring the band back towards your chest.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.", "Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.", "Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.", "Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.", "Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.", "Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Paso Atrás con Alcance por Encima de la Cabeza', 'posterior-step-to-overhead-reach.gif', 'waist', '["Stand with your feet hip-width apart and your arms by your sides.", "Take a step back with your right foot, landing on the ball of your foot.", "Bend your left knee and lower your body into a lunge position.", "As you lower into the lunge, simultaneously reach your arms overhead.", "Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.", "Repeat the movement on the other side, stepping back with your left foot and bending your right knee.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo.", "Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.", "Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada.", "Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza.", "Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante.", "Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Pica Colgado', 'hanging-pike.gif', 'waist', '["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.", "Engage your core and lift your legs up towards the bar, keeping them straight.", "Continue lifting until your body forms a ''V'' shape, with your legs parallel to the ground.", "Hold the position for a moment, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.", "Activa el core y levanta las piernas hacia la barra, manteniéndolas rectas.", "Continúa levantando hasta que el cuerpo forme una ''V'', con las piernas paralelas al suelo.", "Mantén la posición por un momento, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha Alta a Baja (Power Point)', 'power-point-plank.gif', 'waist', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.", "Engage your core and squeeze your glutes to maintain a stable position.", "Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.", "Hold this position for the desired amount of time, keeping your core and glutes engaged.", "To return to the starting position, push through your forearms and lift your body back up into a high plank position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.", "Activa el core y aprieta los glúteos para mantener una posición estable.", "Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies.", "Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados.", "Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta.", "Repite el número de repeticiones deseado."]'),
  ('Plancha Completa (Planche)', 'full-planche.gif', 'waist', '["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.", "Engage your core and slowly shift your weight forward, lifting your feet off the ground.", "Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.", "Hold this position for as long as you can, maintaining a straight body line.", "Slowly lower your feet back to the ground and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los dedos apuntando hacia adelante.", "Activa el core y desplaza lentamente el peso hacia adelante, levantando los pies del suelo.", "Continúa desplazando el peso hacia adelante hasta que el cuerpo quede paralelo al suelo, equilibrándote sobre las manos.", "Mantén esta posición todo el tiempo que puedas, conservando una línea corporal recta.", "Baja lentamente los pies de nuevo al suelo y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha con Piernas Abiertas (Straddle Planche)', 'straddle-planche.gif', 'waist', '["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.", "Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.", "Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados.", "Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.", "Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha de Rana', 'frog-planche.gif', 'waist', '["Start in a push-up position with your hands shoulder-width apart and your feet together.", "Bend your elbows and lower your body towards the ground, keeping your back straight.", "As you lower your body, lift your feet off the ground and bring your knees towards your chest.", "Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión de brazos con las manos separadas a la altura de los hombros y los pies juntos.", "Dobla los codos y baja el cuerpo hacia el suelo, manteniendo la espalda recta.", "Mientras bajas el cuerpo, levanta los pies del suelo y lleva las rodillas hacia el pecho.", "Mantén esta posición durante unos segundos, luego extiende las piernas de nuevo y empújate hacia arriba a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha de Rodillas con Toque de Hombro', 'kneeling-plank-tap-shoulder-male.gif', 'waist', '["Start in a kneeling position with your hands on the ground, shoulder-width apart.", "Extend your legs behind you, resting on your toes, and lift your body into a plank position.", "Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.", "Return the hand to the ground and repeat with the other hand.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros.", "Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha.", "Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto.", "Devuelve la mano al suelo y repite con la otra mano.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Plancha Frontal con Giro', 'front-plank-with-twist.gif', 'waist', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.", "Engage your core and glutes to maintain a stable position.", "Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.", "Keep your hips and legs stable as you twist.", "Hold for a moment, then return to the starting position.", "Repeat the twist on the left side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.", "Activa el core y los glúteos para mantener una posición estable.", "Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo.", "Mantén las caderas y las piernas estables mientras giras.", "Mantén la posición por un momento, luego regresa a la posición inicial.", "Repite el giro hacia el lado izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Plancha Inclinada (Lean Planche)', 'lean-planche.gif', 'waist', '["Start in a push-up position with your hands shoulder-width apart and your body straight.", "Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.", "Keep your elbows slightly bent and your body straight as you lean forward.", "Hold this position for a few seconds, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de flexión con las manos separadas a la altura de los hombros y el cuerpo recto.", "Activa el core y traslada lentamente el peso hacia adelante, llevando los hombros más allá de las manos.", "Mantén los codos ligeramente flexionados y el cuerpo recto mientras te inclinas hacia adelante.", "Mantén esta posición durante unos segundos, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Plancha Inversa con Elevación de Pierna', 'reverse-plank-with-leg-lift.gif', 'waist', '["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.", "Press through your hands and lift your hips off the ground, coming into a reverse plank position.", "Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.", "Hold for a moment, then lower your leg back down.", "Repeat with the other leg.", "Continue alternating legs for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies.", "Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa.", "Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo.", "Mantén la posición por un momento y luego baja la pierna de nuevo.", "Repite con la otra pierna.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Plancha Lateral Inclinada', 'bodyweight-incline-side-plank.gif', 'waist', '["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "Hold this position for the desired amount of time.", "Lower your hips back down to the ground and repeat on the other side."]', '["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.", "Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.", "Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.", "Mantén esta posición durante el tiempo deseado.", "Baja las caderas de nuevo al suelo y repite hacia el otro lado."]'),
  ('Plancha Lateral sobre el Antebrazo', 'side-bridge-v-2.gif', 'waist', '["Lie on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "Hold this position for the desired amount of time.", "Lower your hips back down to the starting position.", "Repeat on the other side."]', '["Túmbate de lado con las piernas extendidas y una sobre la otra.", "Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.", "Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.", "Mantén esta posición durante el tiempo deseado.", "Baja las caderas de vuelta a la posición inicial.", "Repite del otro lado."]'),
  ('Press Inclinado Lateral con Kettlebell (Bent Press)', 'kettlebell-bent-press.gif', 'waist', '["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.", "Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.", "Rotate your torso to the left, shifting your weight onto your left foot.", "Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.", "As you lower, keep your eyes on the kettlebell and your chest lifted.", "Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.", "As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en la mano derecha.", "Dobla ligeramente las rodillas y empuja la pesa rusa por encima de la cabeza con el brazo derecho, manteniendo el codo bloqueado.", "Rota el torso hacia la izquierda, trasladando tu peso al pie izquierdo.", "Flexiona la rodilla izquierda y baja el torso hacia el suelo, manteniendo el brazo derecho extendido por encima de la cabeza.", "Mientras bajas, mantén la mirada en la pesa rusa y el pecho elevado.", "Cuando tu mano izquierda toque el suelo, empuja con el pie izquierdo y estira la pierna izquierda, llevando las caderas hacia adelante.", "Mientras llevas las caderas hacia adelante, usa el core y el brazo derecho para empujar la pesa rusa de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Rueda Abdominal Asistida con Banda Elástica', 'band-assisted-wheel-rollerout.gif', 'waist', '["Kneel on the floor and hold the handles of the band with both hands, palms facing down.", "Place the band on the ground in front of you and position your hands shoulder-width apart.", "Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.", "Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.", "Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.", "Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.", "Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rueda Abdominal con Barra', 'barbell-rollerout.gif', 'waist', '["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.", "Roll the barbell forward, extending your arms and keeping your core engaged.", "Continue rolling forward until your body is fully extended and your arms are overhead.", "Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.", "Repeat for the desired number of repetitions."]', '["Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.", "Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.", "Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.", "Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.", "Repite el número de repeticiones deseado."]'),
  ('Rueda Abdominal con Barra desde Banco', 'barbell-rollerout-from-bench.gif', 'waist', '["Start by kneeling on the floor with a barbell placed on a bench in front of you.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.", "Continue rolling the barbell forward until your body is fully extended and your arms are overhead.", "Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.", "Repeat for the desired number of repetitions."]', '["Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.", "Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.", "Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rueda Abdominal de Pie', 'standing-wheel-rollerout.gif', 'waist', '["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.", "Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.", "Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.", "Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti.", "Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado.", "Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible.", "Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rueda Abdominal de Pie con Barra', 'barbell-standing-ab-rollerout.gif', 'waist', '["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.", "Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.", "Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.", "Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos.", "Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos.", "Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza.", "Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla Profunda (Potty Squat)', 'potty-squat.gif', 'waist', '["Stand with your feet shoulder-width apart, toes pointing slightly outward.", "Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.", "Keep your chest up and your back straight throughout the movement.", "Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.", "Pause for a moment at the bottom, then push through your heels to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.", "Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sierra con Rodillo (Body Saw)', 'roller-body-saw.gif', 'waist', '["Start in a plank position with your forearms on the roller and your body in a straight line.", "Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.", "Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta.", "Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control.", "Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Slam a 1 Brazo con Balón Medicinal', 'one-arm-slam-with-medicine-ball.gif', 'waist', '["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.", "Bend your knees slightly and engage your core.", "Raise the medicine ball above your head, fully extending your arm.", "Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.", "Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura.", "Flexiona ligeramente las rodillas y activa el core.", "Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo.", "Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia.", "Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado."]'),
  ('Sprint Colgado (Wind Sprints)', 'wind-sprints.gif', 'waist', '["Find an open space or a track to perform the exercise.", "Start by standing with your feet shoulder-width apart.", "Begin running as fast as you can, pumping your arms and driving your knees up.", "Continue sprinting for a specific distance or time period.", "Rest and repeat for the desired number of repetitions."]', '["Busca un espacio abierto o una pista para realizar el ejercicio.", "Comienza de pie con los pies separados a la altura de los hombros.", "Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas.", "Continúa el sprint durante una distancia o periodo de tiempo específico.", "Descansa y repite el número de repeticiones deseado."]'),
  ('Toque de Hombro en Plancha Alta', 'shoulder-tap.gif', 'waist', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.", "Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.", "Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.", "Continue alternating shoulder taps while keeping your hips and torso stable.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo.", "Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda.", "Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables.", "Repite el número de repeticiones deseado."]'),
  ('Toque de Pie con Giro en Posición de Cangrejo', 'crab-twist-toe-touch.gif', 'waist', '["Start by sitting on the ground with your knees bent and feet flat on the floor.", "Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.", "Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.", "Return to the starting position and repeat on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo.", "Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo.", "Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie.", "Regresa a la posición inicial y repite del otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Toque de Puntas de Lado a Lado', 'side-to-side-toe-touch-male.gif', 'waist', '["Stand with your feet shoulder-width apart and your arms extended to the sides.", "Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.", "Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.", "Repeat the side-to-side bending motion for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.", "Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado.", "Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado.", "Repite el movimiento de flexión lateral el número de repeticiones deseado."]'),
  ('Toques de Talón Alternos', 'alternate-heel-touchers.gif', 'waist', '["Lie flat on your back with your knees bent and feet flat on the ground.", "Extend your arms straight out to the sides, parallel to the ground.", "Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.", "Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Extiende los brazos hacia los lados, paralelos al suelo.", "Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.", "Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('V-Sit en el Suelo', 'v-sit-on-floor.gif', 'waist', '["Sit on the floor with your legs extended in front of you.", "Lean back slightly and lift your legs off the ground, keeping them straight.", "Simultaneously, lift your upper body off the ground and reach your arms towards your legs.", "Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas.", "Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas.", "Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('V-Up Alterno con Banda Elástica', 'band-alternating-v-up.gif', 'waist', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.", "As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.", "Repeat the movement, alternating the position of your legs with each repetition.", "Continue for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.", "Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.", "Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.", "Repite el movimiento, alternando la posición de las piernas en cada repetición.", "Continúa durante el número de repeticiones deseado."]'),
  ('V-Up con Banda Elástica', 'band-v-up.gif', 'waist', '["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.", "Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.", "Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.", "Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Volteo Judo en Polea', 'cable-judo-flip.gif', 'waist', '["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with both hands at chest level, palms facing down.", "Engage your core and rotate your torso to the right, pulling the cable across your body.", "As you rotate, pivot your back foot and allow your hips to rotate naturally.", "Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.", "Return to the starting position by reversing the movement, rotating your torso back to the center.", "Repeat the movement on the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo.", "Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo.", "Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural.", "Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro.", "Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro.", "Repite el movimiento en el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]');
insert into public.exercises (name, video_url, body_part_id, instructions_en, instructions_es)
